// ---------------------------------------------------------------------------
// API client. The server is the source of truth; nothing is cached to the
// browser. `actor` is sent on every mutation so the audit log means something.
// ---------------------------------------------------------------------------
const ACTOR_KEY = "ime-actor";
const getActor = () => { try { return window.localStorage.getItem(ACTOR_KEY) || ""; } catch (e) { return ""; } };
const setActorStored = (v) => { try { window.localStorage.setItem(ACTOR_KEY, v); } catch (e) {} };

async function api(method, path, body) {
  const res = await fetch(path, {
    method,
    headers: { "content-type": "application/json", "x-actor": getActor() || "unknown" },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  if (res.status === 401) { window.location.href = "/"; throw new Error("Session expired — please sign in again."); }
  if (!res.ok) {
    const e = await res.json().catch(() => ({ error: res.statusText }));
    throw new Error(e.error || `${method} ${path} failed (${res.status})`);
  }
  return res.status === 204 ? null : res.json();
}

const CORE_FROM_CODE = { PSYCH: "Psych", ORTHO: "Ortho", NEURO: "Neuro", CARDIO: "Cardio", OTHER: "Other" };
const CODE_FROM_CORE = { Psych: "PSYCH", Ortho: "ORTHO", Neuro: "NEURO", Cardio: "CARDIO", Other: "OTHER" };

/** Wire physician -> the record shape this UI was built around. */
function adaptPhysician(p) {
  const locs = p.locations || [];
  // Confirmation is per-location in the database (correct). The row badge shows
  // the weakest link, because that is what you can actually stand behind.
  const rank = { needs_confirm: 0, out_of_state: 1, assumed: 2, confirmed: 3 };
  const weakest = locs.length
    ? locs.reduce((a, l) => (rank[l.confirmation_status] < rank[a] ? l.confirmation_status : a), "confirmed")
    : "needs_confirm";
  return {
    id: p.id,
    name: p.credentials ? `${p.full_name}, ${p.credentials}` : p.full_name,
    specialty: p.specialty_detail || p.specialty_code || "",
    core: CORE_FROM_CODE[p.specialty_code] || "Other",
    detail: p.specialty_detail || "",
    email: p.email || "", phone: p.phone || "", rawAddress: p.source_address_raw || "",
    qme: !!p.is_qme, flag: p.notes || "",
    org: p.organization_name || null,
    travel: p.travel_mode || "none", travelRadius: p.radius_miles || null,
    conf: { confirmed: "documented", assumed: "assumed", needs_confirm: "needs_confirm", out_of_state: "out_of_state" }[weakest],
    sites: locs.map((l) => ({
      id: l.id, region: "", city: l.city, lat: l.lat, lng: l.lng,
      type: l.site_type === "flyin" ? "travel" : "owned",
      conf: l.confirmation_status,
    })),
  };
}
const adaptRegion = (r) => ({
  id: r.id, name: r.name, pop: r.population_m, fly: r.is_flyin_corridor ? 1 : 0,
  pin: r.pin_label, lat: r.pin_lat, lng: r.pin_lng, covers: r.covers || "",
  mph: r.effective_mph, radius_override: r.radius_override,
});

const CORE = ["Psych", "Ortho", "Neuro", "Cardio"];
const ROAD = 1.27, DEFAULT_SPEED = 48;

const C = {
  ground: "#F2F4F3", surface: "#FFFFFF", ink: "#10201F", muted: "#6B7A78",
  rule: "#D8DEDC", ruleSoft: "#E7EBEA",
  owned: "#1D6B5C", ownedBg: "#E4EFEC",
  travel: "#5B4B8A", travelBg: "#EAE7F2",
  none: "#B3261E", noneBg: "#FAEAE8",
  flag: "#A66A00", flagBg: "#FBF0DD",
  near: "#0F4A3E",
};
const MONO = "'IBM Plex Mono', ui-monospace, monospace";
const SANS = "'IBM Plex Sans', system-ui, sans-serif";
const COND = "'IBM Plex Sans Condensed', 'IBM Plex Sans', sans-serif";

function haversine(la1, lo1, la2, lo2) {
  const R = 3958.8, r = Math.PI / 180;
  const dLa = (la2 - la1) * r, dLo = (lo2 - lo1) * r;
  const h = Math.sin(dLa / 2) ** 2 + Math.cos(la1 * r) * Math.cos(la2 * r) * Math.sin(dLo / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}
function driveMinutes(site, region) {
  if (site.lat == null) return null;
  const miles = haversine(site.lat, site.lng, region.lat, region.lng) * ROAD;
  return { min: Math.round((miles / (SPEED[region.name] || DEFAULT_SPEED)) * 60), miles: Math.round(miles) };
}

export default function Console() {
  const [providers, setProviders] = useState(SEED);
  const [standard, setStandard] = useState(60);
  const [radii, setRadii] = useState({});
  const [specs, setSpecs] = useState(() => new Set(CORE));
  const [targets, setTargets] = useState(() => {
    const t = {};
    REGIONS.forEach((r) => CORE.forEach((c) => (t[r.name + "|" + c] = 1)));
    return t;
  });
  const [outreach, setOutreach] = useState([]);
  const [tab, setTab] = useState("ledger");
  const [openProvider, setOpenProvider] = useState(null);   // set from the map, consumed by the Providers tab
  const [openRegion, setOpenRegion] = useState(null);
  const [status, setStatus] = useState("loading");

  const [err, setErr] = useState(null);
  const [actor, setActor] = useState(getActor());
  const [me, setMe] = useState(null);
  const [asOf, setAsOf] = useState(null);

  const load = async () => {
    try {
      const [regions, phys, settings, targetRows, queue, me] = await Promise.all([
        api("GET", "/api/regions"), api("GET", "/api/physicians"),
        api("GET", "/api/settings"), api("GET", "/api/targets"),
        api("GET", "/api/outreach?status=all"), api("GET", "/api/auth/me").catch(() => null),
      ]);
      setOutreach(queue);
      if (me) { setMe(me); setActor(me.name); }
      REGIONS = regions.map(adaptRegion);
      FLYIN = REGIONS.filter((r) => r.fly).map((r) => r.name);
      SPEED = Object.fromEntries(REGIONS.map((r) => [r.name, r.mph]));
      const rad = {};
      REGIONS.forEach((r) => { if (r.radius_override != null) rad[r.name] = r.radius_override; });
      setRadii(rad);
      setStandard(parseInt(settings.standard_minutes || "60", 10));
      setAsOf(settings.data_as_of || null);
      const t = {};
      targetRows.forEach((row) => (t[row.region + "|" + CORE_FROM_CODE[row.specialty]] = row.target_count));
      setTargets(t);
      setProviders(phys.map(adaptPhysician));
      setStatus("ready"); setErr(null);
    } catch (e) { setErr(e.message); setStatus("error"); }
  };
  useEffect(() => { load(); }, []);

  const withSave = async (fn) => {
    setStatus("saving");
    try { await fn(); await load(); setStatus("saved"); setTimeout(() => setStatus("ready"), 1000); }
    catch (e) { setErr(e.message); setStatus("error"); }
  };

  const activeCore = CORE.filter((c) => specs.has(c));

  const limitFor = (name) => (radii[name] != null ? radii[name] : standard);

  // reach: for each provider, the nearest site to every pin within that pin's radius
  const reach = useMemo(() => {
    const map = {};
    providers.forEach((p) => {
      map[p.id] = {};
      REGIONS.forEach((r) => {
        let best = null;
        p.sites.forEach((s) => {
          const dm = driveMinutes(s, r);
          if (!dm) return;
          if (!best || dm.min < best.min) best = { ...dm, city: s.city, type: s.type };
        });
        if (best && best.min <= (radii[r.name] != null ? radii[r.name] : standard)) map[p.id][r.name] = best;
      });
    });
    return map;
  }, [providers, standard, radii]);

  const cellFor = (region, core) => {
    const hits = providers
      .filter((p) => p.core === core && reach[p.id] && reach[p.id][region])
      .map((p) => ({ p, r: reach[p.id][region] }))
      .sort((a, b) => a.r.min - b.r.min);
    return {
      n: hits.length,
      hits,
      nearest: hits.length ? hits[0].r.min : null,
      anyOffice: hits.some((h) => h.r.type === "owned"),
      allTravel: hits.length > 0 && hits.every((h) => h.r.type === "travel"),
    };
  };

  const totals = useMemo(() => {
    let covered = 0, cells = 0, metroGap = 0, flyGap = 0, popGapped = 0, flyOnly = 0, single = 0, within30 = 0;
    REGIONS.forEach((r) => {
      let zero = false;
      activeCore.forEach((c) => {
        cells++;
        const cell = cellFor(r.name, c);
        if (cell.n === 0) { r.fly ? flyGap++ : metroGap++; zero = true; }
        else {
          covered++;
          if (cell.nearest <= 30) within30++;
          if (cell.allTravel) flyOnly++;
          if (cell.n === 1) single++;
        }
      });
      if (zero && !r.fly) popGapped += r.pop;
    });
    return { covered, cells, metroGap, flyGap, popGapped, flyOnly, single, within30 };
  }, [reach, providers, standard, radii, specs]);

  
  const regionByName = (n) => REGIONS.find((r) => r.name === n);
  const specIdOf = (core) => ({ Psych: 1, Ortho: 2, Neuro: 3, Cardio: 4, Other: 5 })[core];

  const setTarget = (region, core, v) => withSave(() =>
    api("PUT", "/api/targets", { region_id: regionByName(region).id, specialty_id: specIdOf(core), target_count: Math.max(0, parseInt(v) || 0) }));
  const setAllTargets = (v) => withSave(() => api("PUT", "/api/targets", { all: v }));
  const setStandardSrv = (v) => withSave(async () => {
    await api("PUT", "/api/settings/standard_minutes", { value: v });
    for (const r of REGIONS) if (r.radius_override != null) await api("PUT", `/api/regions/${r.id}/radius`, { minutes: null });
  });
  const setRadius = (name, v) => withSave(() => api("PUT", `/api/regions/${regionByName(name).id}/radius`, { minutes: v }));
  const clearRadius = (name) => withSave(() => api("PUT", `/api/regions/${regionByName(name).id}/radius`, { minutes: null }));
  const resolveItem = (id, note) => withSave(() =>
    api("PATCH", `/api/outreach/${id}`, { status: "resolved", outcome_note: note || null }));
  const reopenItem = (id) => withSave(() =>
    api("PATCH", `/api/outreach/${id}`, { status: "open", outcome_note: null }));
  const assignItem = (id, who) => withSave(() =>
    api("PATCH", `/api/outreach/${id}`, { assigned_to: who || null, status: who ? "in_progress" : "open" }));

  const reset = () => load();

  return (
    <div style={{ background: C.ground, minHeight: "100vh", fontFamily: SANS, color: C.ink }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500&family=IBM+Plex+Sans+Condensed:wght@400;600&family=IBM+Plex+Sans:wght@400;500;600&display=swap');
        * { box-sizing: border-box; }
        .rowhover:hover { background: #EAEEED !important; }
        button:focus-visible, input:focus-visible, select:focus-visible { outline: 2px solid #5B4B8A; outline-offset: 1px; }
        input, select { font-family: inherit; }
        @media (prefers-reduced-motion: reduce) { * { transition: none !important; } }
      `}</style>

      <div style={{ maxWidth: 1180, margin: "0 auto", padding: "28px 20px 60px" }}>
        {err && (
          <div style={{ background: C.noneBg, border: `1px solid ${C.none}`, color: C.none, padding: "9px 12px", marginBottom: 14, fontSize: 12, display: "flex", gap: 10, alignItems: "center" }}>
            <span style={{ flex: 1 }}>{err}</span>
            <button onClick={() => load()} style={{ background: "none", border: `1px solid ${C.none}`, color: C.none, padding: "3px 9px", fontSize: 11, cursor: "pointer", fontFamily: SANS }}>Retry</button>
          </div>
        )}
        <header style={{ marginBottom: 22 }}>
          <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", flexWrap: "wrap", gap: 10 }}>
            <div>
              <div style={{ fontFamily: MONO, fontSize: 10.5, letterSpacing: "0.14em", color: C.muted, textTransform: "uppercase", marginBottom: 5 }}>
                California IME network
              </div>
              <h1 style={{ fontFamily: COND, fontSize: 31, fontWeight: 600, margin: 0, letterSpacing: "-0.01em" }}>Coverage console</h1>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            {me ? <AccountMenu me={me} /> :
              <span style={{ fontFamily: MONO, fontSize: 10, color: C.muted }}>{actor}</span>}
            {asOf && <span style={{ fontFamily: MONO, fontSize: 9.5, color: C.muted }}>source {asOf}</span>}
            <div style={{ fontFamily: MONO, fontSize: 10.5, color: status === "error" ? C.none : C.muted }}>
              {status === "saving" ? "saving…" : status === "saved" ? "saved" : status === "error" ? "error" : status === "loading" ? "loading…" : "live"}
            </div>
          </div>
          </div>

          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(146px,1fr))", gap: 1, background: C.rule, border: `1px solid ${C.rule}`, marginTop: 18 }}>
            <Kpi label="Pins covered" value={`${totals.covered}/${totals.cells}`} sub={`within ${standard} min`} />
            <Kpi label="Metro gaps" value={totals.metroGap} sub="recruit into these" tone={totals.metroGap > 0 ? C.none : C.owned} />
            <Kpi label="Corridor gaps" value={totals.flyGap} sub="cover by fly-in" tone={C.travel} />
            <Kpi label="Within 30 min" value={totals.within30} sub="of the pin — the ideal" tone={C.near} />
            <Kpi label="Population in a gapped metro" value={`${totals.popGapped.toFixed(1)}M`} sub="missing ≥1 core specialty" />
            <Kpi label="No backup" value={totals.single} sub="one provider deep" tone={totals.single > 0 ? C.flag : C.owned} />
          </div>
          <SpecFilter specs={specs} setSpecs={setSpecs} providers={providers} activeCore={activeCore} />
        </header>

        <nav style={{ display: "flex", gap: 2, borderBottom: `1px solid ${C.rule}`, marginBottom: 20 }}>
          {[["ledger", "Coverage ledger"], ["map", "Map"], ["providers", `Providers (${providers.length})`], ["confirm", `Call sheet (${outreach.filter((o) => o.status === "open" || o.status === "in_progress").length})`]].map(([k, l]) => (
            <button key={k} onClick={() => setTab(k)} style={{
              background: tab === k ? C.surface : "transparent", border: "none",
              borderTop: `2px solid ${tab === k ? C.ink : "transparent"}`,
              borderLeft: `1px solid ${tab === k ? C.rule : "transparent"}`,
              borderRight: `1px solid ${tab === k ? C.rule : "transparent"}`,
              padding: "11px 18px", cursor: "pointer", fontSize: 13, fontWeight: tab === k ? 600 : 400,
              color: tab === k ? C.ink : C.muted, marginBottom: -1, fontFamily: SANS,
            }}>{l}</button>
          ))}
          <div style={{ flex: 1 }} />
          <button onClick={reset} style={{ background: "transparent", border: "none", color: C.muted, fontSize: 11, cursor: "pointer", padding: "11px 4px" }}>Reload from server</button>
        </nav>

        {tab === "ledger" && <Ledger {...{ cellFor, targets, setTarget, setAllTargets, standard, setStandard: setStandardSrv, openRegion, setOpenRegion, limitFor, activeCore }} />}
        {tab === "map" && <MapView {...{ providers, reach, cellFor, limitFor, standard, radii, specs, setSpecs, activeCore, openRecord: (pid) => { setOpenProvider(pid); setTab("providers"); }, setRadius, clearRadius }} />}
        {tab === "providers" && <Providers {...{ providers, reload: load, actor, specs, reach, standard, openProvider, setOpenProvider }} />}
        {tab === "confirm" && <CallSheet {...{ outreach, resolveItem, reopenItem, assignItem, actor }} />}
      </div>
    </div>
  );
}

const CITY_DATA = CITY_STR.split(";").map((s) => { const [n, la, lo, p] = s.split("|"); return { n, la: +la, lo: +lo, p: +p }; });
const ZIP_NAMES = ZIPNAME_STR.split(";");
const ZIP_DATA = (() => { const m = {}; ZIP_STR.split(";").forEach((s) => { const [z, la, lo, i] = s.split("|"); m[z] = { la: +la, lo: +lo, city: ZIP_NAMES[+i] }; }); return m; })();
const CITY_INDEX = (() => { const m = {}; CITY_DATA.forEach((c) => { const k = c.n.toLowerCase(); if (!m[k] || c.p > m[k].p) m[k] = c; }); return m; })();
// exposed so a standalone build can geocode without a server
if (typeof window !== "undefined") { window.__CITY = CITY_INDEX; window.__ZIP = ZIP_DATA; }

function radiusMiles(regionName, minutes) { return (minutes * (SPEED[regionName] || DEFAULT_SPEED)) / 60 / ROAD; }
function minutesBetween(la1, lo1, la2, lo2, speedKey) {
  const miles = haversine(la1, lo1, la2, lo2) * ROAD;
  return { min: Math.round((miles / (SPEED[speedKey] || DEFAULT_SPEED)) * 60), miles: Math.round(miles) };
}
function nearestPin(la, lo) { let b = null; REGIONS.forEach((r) => { const d = haversine(la, lo, r.lat, r.lng); if (!b || d < b.d) b = { r, d }; }); return b.r; }
function resolveQuery(q) {
  const s = q.trim(); if (!s) return null;
  if (/^\d{5}$/.test(s)) { const z = ZIP_DATA[s]; return z ? { lat: z.la, lng: z.lo, label: `${z.city} ${s}`, kind: "ZIP" } : null; }
  const c = CITY_INDEX[s.toLowerCase()];
  if (c) return { lat: c.la, lng: c.lo, label: c.n, kind: "City" };
  const hit = CITY_DATA.find((x) => x.n.toLowerCase().startsWith(s.toLowerCase()));
  return hit ? { lat: hit.la, lng: hit.lo, label: hit.n, kind: "City" } : null;
}
const ALL_SPECS = ["Psych", "Ortho", "Neuro", "Cardio", "Other"];
const RMIN = 15, RMAX = 150, RSTOPS = [15, 30, 60, 90, 150];
const NOLIMIT = 9999;
const isNoLimit = (v) => v >= NOLIMIT;
const fmtMin = (m) => (m >= 120 ? `${(m / 60).toFixed(1)}h` : `${m}m`);
const SPEC_TONE = { Psych: "#4A3AA7", Ortho: "#1D6B5C", Neuro: "#2A78D6", Cardio: "#D85A30", Other: "#888780" };
function labelFloor(k) { return k < 1.6 ? 250000 : k < 3 ? 100000 : k < 6 ? 45000 : k < 12 ? 20000 : 10000; }

function MapView({ providers, reach, cellFor, limitFor, standard, radii, specs, setSpecs, activeCore, openRecord, setRadius, clearRadius }) {
  const [sel, setSel] = useState("LA Basin");
  const [showAll, setShowAll] = useState(false);
  const [showBorders, setShowBorders] = useState(true);
  const [showLabels, setShowLabels] = useState(true);
  const [query, setQuery] = useState("");
  const [plot, setPlot] = useState(null);
  const [tf, setTf] = useState({ k: 1, x: 0, y: 0 });
  const [dims, setDims] = useState({ w: 620, h: 730 });
  const svgRef = React.useRef(null);
  const zoomRef = React.useRef(null);
  const boxRef = React.useRef(null);
  const W = dims.w, H = dims.h;

  useEffect(() => {
    if (!boxRef.current) return;
    boxRef.current.style.width = "620px";
    boxRef.current.style.height = "730px";
    if (typeof ResizeObserver === "undefined") return;
    const ro = new ResizeObserver((es) => {
      const r = es[0].contentRect;
      setDims({ w: Math.max(260, Math.round(r.width)), h: Math.max(300, Math.round(r.height)) });
    });
    ro.observe(boxRef.current);
    return () => ro.disconnect();
  }, []);
  const sizeTo = (w, h) => {
    if (!boxRef.current) return;
    const p = boxRef.current.parentElement;
    boxRef.current.style.width = w === "fit" ? Math.max(300, p.clientWidth) + "px" : w + "px";
    boxRef.current.style.height = h + "px";
  };

  const { path, proj } = useMemo(() => {
    const fc = { type: "FeatureCollection", features: [{ type: "Feature", geometry: CA.main }] };
    const pr = d3.geoMercator().fitExtent([[12, 12], [W - 12, H - 12]], fc);
    return { path: d3.geoPath(pr), proj: pr };
  }, [W, H]);

  useEffect(() => {
    if (!svgRef.current) return;
    const s = d3.select(svgRef.current);
    const z = d3.zoom().scaleExtent([1, 60]).translateExtent([[0, 0], [W, H]]).extent([[0, 0], [W, H]])
      .on("zoom", (e) => setTf({ k: e.transform.k, x: e.transform.x, y: e.transform.y }));
    s.call(z).on("dblclick.zoom", null);
    zoomRef.current = { z, s };
    return () => { s.on(".zoom", null); };
  }, []);
  useEffect(() => {
    if (!zoomRef.current) return;
    zoomRef.current.z.extent([[0, 0], [W, H]]).translateExtent([[0, 0], [W, H]]);
    zoomRef.current.s.call(zoomRef.current.z.transform, d3.zoomIdentity);
  }, [W, H]);
  const zoomBy = (f) => zoomRef.current && zoomRef.current.s.transition().duration(220).call(zoomRef.current.z.scaleBy, f);
  const zoomReset = () => zoomRef.current && zoomRef.current.s.transition().duration(300).call(zoomRef.current.z.transform, d3.zoomIdentity);
  const zoomTo = (lng, lat, k = 9) => {
    if (!zoomRef.current) return;
    const p = proj([lng, lat]);
    const t = d3.zoomIdentity.translate(W / 2 - p[0] * k, H / 2 - p[1] * k).scale(k);
    zoomRef.current.s.transition().duration(500).call(zoomRef.current.z.transform, t);
  };

  const K = tf.k;
  const toScreen = (xy) => [xy[0] * K + tf.x, xy[1] * K + tf.y];

  const cells = useMemo(() => {
    const pts = REGIONS.map((r) => proj([r.lng, r.lat]));
    const vor = d3.Delaunay.from(pts).voronoi([0, 0, W, H]);
    return REGIONS.map((r, i) => ({ r, d: vor.renderCell(i) }));
  }, [proj, W, H]);

  const gapsOf = (r) => activeCore.filter((c) => cellFor(r.name, c).n === 0).length;
  const toneOf = (r) => {
    if (!activeCore.length) return C.muted;
    const g = gapsOf(r);
    return g === 0 ? C.owned : r.fly ? C.travel : g === activeCore.length ? C.none : C.flag;
  };

  const labels = useMemo(() => {
    if (!showLabels) return [];
    const floor = labelFloor(K), placed = [], out = [];
    for (const c of CITY_DATA) {
      if (c.p < floor) continue;
      const xy = toScreen(proj([c.lo, c.la]));
      if (xy[0] < -20 || xy[0] > W + 20 || xy[1] < -10 || xy[1] > H + 10) continue;
      const w = c.n.length * 4.4 + 8, h = 10;
      const box = { x: xy[0] + 4, y: xy[1] - 7, w, h };
      if (placed.some((b) => !(box.x + box.w < b.x || b.x + b.w < box.x || box.y + box.h < b.y || b.y + b.h < box.y))) continue;
      placed.push(box); out.push({ c, xy });
      if (out.length > 90) break;
    }
    return out;
  }, [proj, showLabels, K, tf.x, tf.y]);

  const scaleBar = useMemo(() => {
    const c = proj.invert([W / 2, H / 2]);
    const p1 = proj([c[0], c[1]]), p2 = proj([c[0] + 1, c[1]]);
    const pxPerMi = (Math.abs(p2[0] - p1[0]) * K) / (69.17 * Math.cos((c[1] * Math.PI) / 180));
    const mi = [1, 2, 5, 10, 25, 50, 100, 200].find((t) => t * pxPerMi > 60) || 200;
    return { mi, px: Math.round(mi * pxPerMi) };
  }, [K, proj]);

  const circleFor = (r) => d3.geoCircle().center([r.lng, r.lat]).radius(Math.min(89, (radiusMiles(r.name, limitFor(r.name)) / 3958.8) * (180 / Math.PI)))();
  const selR = REGIONS.find((x) => x.name === sel);
  const selLimit = limitFor(sel);
  const overridden = radii[sel] != null;

  const runSearch = () => {
    const hit = resolveQuery(query);
    if (!hit) { setPlot({ error: query }); return; }
    const region = nearestPin(hit.lat, hit.lng);
    setPlot({ ...hit, region }); setSel(region.name); zoomTo(hit.lng, hit.lat, 12);
  };

  const plotResults = useMemo(() => {
    if (!plot || plot.error) return null;
    const rows = [];
    providers.forEach((p) => {
      let best = null;
      p.sites.forEach((s) => {
        if (s.lat == null) return;
        const d = minutesBetween(plot.lat, plot.lng, s.lat, s.lng, plot.region.name);
        if (!best || d.min < best.min) best = { ...d, city: s.city, type: s.type };
      });
      if (best) rows.push({ p, ...best });
    });
    rows.sort((a, b) => a.min - b.min);
    const byCore = {}; CORE.forEach((c) => (byCore[c] = rows.filter((r) => r.p.core === c).slice(0, 3)));
    return { rows, byCore };
  }, [plot, providers]);

  const dots = [];
  providers.forEach((p) => { if (!specs.has(p.core)) return; p.sites.forEach((st) => {
    if (st.lat == null) return;
    dots.push({ xy: toScreen(proj([st.lng, st.lat])), p, st, hot: !!(reach[p.id] && reach[p.id][sel]) });
  }); });
  const plotXY = plot && !plot.error ? toScreen(proj([plot.lng, plot.lat])) : null;
  const counts = {}; ALL_SPECS.forEach((c) => (counts[c] = providers.filter((p) => p.core === c && p.sites.length).length));

  return (
    <div>
      <div style={{ display: "flex", gap: 8, marginBottom: 10, flexWrap: "wrap", alignItems: "center" }}>
        <input value={query} onChange={(e) => setQuery(e.target.value)} onKeyDown={(e) => e.key === "Enter" && runSearch()}
          list="ca-places" placeholder="Plot a city or ZIP — Bakersfield, or 93301" style={{ ...inp, width: 262 }} />
        <datalist id="ca-places">{CITY_DATA.slice(0, 200).map((c) => <option key={c.n} value={c.n} />)}</datalist>
        <button onClick={runSearch} style={btn}>Plot</button>
        {plot && <button onClick={() => { setPlot(null); setQuery(""); zoomReset(); }} style={{ ...btn, background: C.surface, color: C.ink, border: `1px solid ${C.rule}` }}>Clear</button>}
        <div style={{ flex: 1 }} />
        {[["Borders", showBorders, setShowBorders], ["Cities", showLabels, setShowLabels], ["All radii", showAll, setShowAll]].map(([l, v, set]) => (
          <label key={l} style={{ display: "flex", alignItems: "center", gap: 5, fontSize: 11.5, color: C.muted, cursor: "pointer" }}>
            <input type="checkbox" checked={v} onChange={(e) => set(e.target.checked)} style={{ accentColor: C.travel }} />{l}
          </label>
        ))}
      </div>

      <div style={{ display: "flex", gap: 6, marginBottom: 10, flexWrap: "wrap", alignItems: "center" }}>
        <span style={{ fontFamily: MONO, fontSize: 9, letterSpacing: "0.08em", textTransform: "uppercase", color: C.muted, marginRight: 3 }}>Map size</span>
        {[["Small", 420, 520], ["Medium", 620, 730], ["Large", 860, 1000], ["Fit width", "fit", 820]].map(([l, w, h]) => (
          <button key={l} onClick={() => sizeTo(w, h)} style={{ background: C.surface, border: `1px solid ${C.rule}`, color: C.ink, padding: "4px 10px", fontSize: 11.5, cursor: "pointer", fontFamily: SANS, borderRadius: 0 }}>{l}</button>
        ))}
        <span style={{ fontFamily: MONO, fontSize: 10, color: C.muted }}>{W}×{H}</span>
        <span style={{ fontSize: 10.5, color: C.muted }}>or drag the corner of the map</span>
      </div>

      <div style={{ display: "flex", gap: 16, alignItems: "flex-start", flexWrap: "wrap" }}>
        <div style={{ flex: "0 0 auto" }}>
        <div ref={boxRef} style={{ background: C.surface, border: `1px solid ${C.rule}`, position: "relative", resize: "both", overflow: "hidden", minWidth: 300, minHeight: 340 }}>
          <svg ref={svgRef} viewBox={`0 0 ${W} ${H}`} style={{ width: "100%", height: "100%", display: "block", cursor: "grab", touchAction: "none" }} role="img"
            aria-label={`Interactive map of California. ${REGIONS.length} regions. ${sel} selected at ${selLimit} minutes.${plot && !plot.error ? " Plotted: " + plot.label : ""}`}>
            <defs><clipPath id="ca-clip"><path d={path(CA.main)} /></clipPath></defs>
            <rect width={W} height={H} fill={C.ground} />
            <g transform={`translate(${tf.x},${tf.y}) scale(${K})`}>
              <path d={path(CA.main)} fill="#EDF1F0" />
              {CA.islands.map((g, i) => <path key={i} d={path(g)} fill="#EDF1F0" stroke={C.rule} strokeWidth={0.6 / K} />)}
              {showBorders && (
                <g clipPath="url(#ca-clip)">
                  {cells.map(({ r, d }) => (
                    <path key={r.name} d={d} fill={toneOf(r)} fillOpacity={r.name === sel ? 0.18 : 0.06}
                      stroke={C.surface} strokeWidth={1 / K} style={{ cursor: "pointer" }} onClick={() => setSel(r.name)}>
                      <title>{r.name} · {r.pin}</title>
                    </path>
                  ))}
                </g>
              )}
              <path d={path(CA.main)} fill="none" stroke={C.muted} strokeWidth={0.9 / K} strokeOpacity="0.5" />
              <g clipPath="url(#ca-clip)">
                {showAll && REGIONS.filter((r) => r.name !== sel && !isNoLimit(limitFor(r.name))).map((r) => (
                  <path key={r.name} d={path(circleFor(r))} fill="none" stroke={toneOf(r)} strokeOpacity="0.4" strokeWidth={0.8 / K} strokeDasharray={`${2 / K} ${2 / K}`} />
                ))}
                {selR && !isNoLimit(limitFor(sel)) && <path d={path(circleFor(selR))} fill={toneOf(selR)} fillOpacity="0.1" stroke={toneOf(selR)} strokeWidth={1.8 / K} />}
              </g>
            </g>

            {labels.map(({ c, xy }) => (
              <g key={c.n} style={{ pointerEvents: "none" }}>
                <circle cx={xy[0]} cy={xy[1]} r="1.5" fill={C.muted} fillOpacity="0.5" />
                <text x={xy[0] + 4} y={xy[1] + 3} style={{ fontFamily: SANS, fontSize: 8.5 }} fill={C.muted} stroke="#EDF1F0" strokeWidth="2.2" paintOrder="stroke">{c.n}</text>
              </g>
            ))}

            {dots.map((d, i) => (
              <circle key={i} cx={d.xy[0]} cy={d.xy[1]} r={d.hot ? 3.4 : 2.4} fill={SPEC_TONE[d.p.core]}
                fillOpacity={d.hot ? 1 : 0.45} stroke={d.st.type === "travel" ? C.surface : "none"} strokeWidth={d.st.type === "travel" ? 1.2 : 0}
                onClick={(e) => { e.stopPropagation(); openRecord(d.p.id); }} style={{ cursor: "pointer" }}>
                <title>{d.p.name}{d.p.org ? ` · ${d.p.org}` : ""} · {d.p.specialty} · {d.st.city}{d.st.type === "travel" ? " (fly-in)" : ""} — click to open</title>
              </circle>
            ))}

            {REGIONS.map((r) => {
              const xy = toScreen(proj([r.lng, r.lat]));
              if (xy[0] < -20 || xy[0] > W + 20 || xy[1] < -20 || xy[1] > H + 20) return null;
              const on = r.name === sel;
              return (
                <g key={r.name} onClick={() => setSel(r.name)} style={{ cursor: "pointer" }}>
                  {on && <circle cx={xy[0]} cy={xy[1]} r="10" fill="none" stroke={toneOf(r)} strokeWidth="1.2" strokeOpacity="0.7" />}
                  <circle cx={xy[0]} cy={xy[1]} r={on ? 5.5 : 3.8} fill={toneOf(r)} stroke={C.surface} strokeWidth="1.4" />
                  {(on || K > 2.2) && <text x={xy[0] + 9} y={xy[1] - 6} style={{ fontFamily: MONO, fontSize: 9.5, fontWeight: 500 }} fill={C.ink} stroke="#EDF1F0" strokeWidth="2.4" paintOrder="stroke">{r.pin}</text>}
                  <title>{r.name} · {r.pin}</title>
                </g>
              );
            })}

            {plotXY && (
              <g style={{ pointerEvents: "none" }}>
                <line x1={plotXY[0]} y1={plotXY[1] - 13} x2={plotXY[0]} y2={plotXY[1] + 13} stroke={C.ink} strokeWidth="1" />
                <line x1={plotXY[0] - 13} y1={plotXY[1]} x2={plotXY[0] + 13} y2={plotXY[1]} stroke={C.ink} strokeWidth="1" />
                <circle cx={plotXY[0]} cy={plotXY[1]} r="5" fill="none" stroke={C.ink} strokeWidth="2" />
                <text x={plotXY[0] + 10} y={plotXY[1] + 17} style={{ fontFamily: MONO, fontSize: 10, fontWeight: 500 }} fill={C.ink} stroke="#EDF1F0" strokeWidth="2.6" paintOrder="stroke">{plot.label}</text>
              </g>
            )}

            <g transform={`translate(14,${H - 22})`} style={{ pointerEvents: "none" }}>
              <line x1="0" y1="0" x2={scaleBar.px} y2="0" stroke={C.ink} strokeWidth="1.4" />
              <line x1="0" y1="-4" x2="0" y2="4" stroke={C.ink} strokeWidth="1.4" />
              <line x1={scaleBar.px} y1="-4" x2={scaleBar.px} y2="4" stroke={C.ink} strokeWidth="1.4" />
              <text x={scaleBar.px / 2} y="-7" textAnchor="middle" style={{ fontFamily: MONO, fontSize: 9 }} fill={C.ink}>{scaleBar.mi} mi</text>
            </g>
          </svg>

          <div style={{ position: "absolute", top: 10, right: 10, display: "flex", flexDirection: "column", gap: 3 }}>
            {[["+", () => zoomBy(1.7)], ["−", () => zoomBy(1 / 1.7)]].map(([l, fn]) => (
              <button key={l} onClick={fn} aria-label={l === "+" ? "Zoom in" : "Zoom out"}
                style={{ width: 27, height: 27, background: C.surface, border: `1px solid ${C.rule}`, cursor: "pointer", fontSize: 14, lineHeight: 1, color: C.ink, borderRadius: 0 }}>{l}</button>
            ))}
            <button onClick={zoomReset} aria-label="Reset zoom" style={{ width: 27, height: 27, background: C.surface, border: `1px solid ${C.rule}`, cursor: "pointer", fontSize: 9, color: C.muted, fontFamily: MONO, borderRadius: 0 }}>CA</button>
          </div>
          <div style={{ position: "absolute", top: 10, left: 10, fontFamily: MONO, fontSize: 9, color: C.muted, background: "rgba(255,255,255,0.75)", padding: "2px 5px" }}>
            {K.toFixed(1)}×
          </div>

          </div>
          <div style={{ display: "flex", gap: 11, padding: "8px 10px", border: `1px solid ${C.rule}`, borderTop: "none", fontSize: 10, color: C.muted, flexWrap: "wrap", background: C.surface }}>
            {[[C.owned, "covered"], [C.flag, "partial"], [C.none, "empty"], [C.travel, "corridor"]].map(([col, l]) => (
              <span key={l} style={{ display: "flex", alignItems: "center", gap: 4 }}><span style={{ width: 7, height: 7, background: col }} />{l}</span>
            ))}
            <span style={{ opacity: 0.75 }}>Scroll to zoom · drag to pan · ringed dots are fly-in</span>
          </div>
        </div>

        <div style={{ flex: "1 1 320px", minWidth: 300 }}>
          {plot && plot.error && (
            <div style={{ background: C.noneBg, padding: "11px 13px", marginBottom: 12, fontSize: 12, color: C.none }}>
              No California city or ZIP matching “{plot.error}”. Try a full ZIP, or a city from the list.
            </div>
          )}
          {plotResults ? (
            <>
              <div style={{ background: C.surface, border: `1px solid ${C.rule}`, padding: "13px 15px", marginBottom: 12 }}>
                <div style={{ fontFamily: MONO, fontSize: 9, letterSpacing: "0.08em", textTransform: "uppercase", color: C.muted, marginBottom: 4 }}>{plot.kind} plotted</div>
                <div style={{ fontFamily: COND, fontSize: 21, fontWeight: 600, marginBottom: 3 }}>{plot.label}</div>
                <div style={{ fontSize: 11.5, color: C.muted }}>Falls in <strong style={{ color: C.ink, fontWeight: 500 }}>{plot.region.name}</strong> · nearest pin {plot.region.pin}</div>
              </div>
              <div style={{ fontFamily: MONO, fontSize: 9, letterSpacing: "0.08em", textTransform: "uppercase", color: C.muted, marginBottom: 7 }}>Closest by specialty</div>
              <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 14 }}>
                {CORE.filter((c) => specs.has(c)).map((c) => {
                  const list = plotResults.byCore[c];
                  return (
                    <div key={c} style={{ background: C.surface, border: `1px solid ${C.rule}`, padding: "9px 11px", minHeight: 78 }}>
                      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 5 }}>
                        <span style={{ display: "flex", alignItems: "center", gap: 6, fontFamily: COND, fontSize: 13, fontWeight: 600 }}>
                          <span style={{ width: 7, height: 7, borderRadius: "50%", background: SPEC_TONE[c] }} />{c}
                        </span>
                        {list.length > 0 && <span style={{ fontFamily: MONO, fontSize: 10, color: list[0].min <= 60 ? C.owned : C.none }}>{list[0].min <= 30 ? "ideal" : list[0].min <= 60 ? "workable" : "over an hour"}</span>}
                      </div>
                      {list.length === 0 ? <div style={{ fontSize: 11, color: C.none }}>Nobody in the network</div> : list.map((r) => (
                        <button key={r.p.id} onClick={() => openRecord(r.p.id)} className="rowhover" title={`Open ${r.p.name.split(",")[0]}`}
                          style={{ display: "flex", gap: 7, fontSize: 11, alignItems: "baseline", padding: "2px", background: "none", border: "none", cursor: "pointer", textAlign: "left", width: "100%" }}>
                          <span style={{ width: 5, height: 5, borderRadius: "50%", background: r.type === "travel" ? C.travel : r.min <= 30 ? C.near : r.min <= 60 ? C.owned : C.rule, flexShrink: 0 }} />
                          <span style={{ flex: 1, color: C.ink }}>{r.p.name.split(",")[0]}</span>
                          <span style={{ fontFamily: MONO, fontSize: 9.5, color: C.muted }}>{r.city}</span>
                          <span style={{ fontFamily: MONO, fontSize: 9.5, color: r.min <= 60 ? C.ink : C.muted, width: 70, textAlign: "right" }}>{r.miles} mi · ~{fmtMin(r.min)}</span>
                        </button>
                      ))}
                    </div>
                  );
                })}
              </div>
              <details>
                <summary style={{ fontSize: 11.5, color: C.travel, cursor: "pointer" }}>Every provider by distance ({plotResults.rows.length})</summary>
                <div style={{ display: "flex", flexDirection: "column", gap: 2, marginTop: 8, maxHeight: 260, overflowY: "auto", background: C.surface, border: `1px solid ${C.rule}`, padding: "8px 10px" }}>
                  {plotResults.rows.map((r) => (
                    <div key={r.p.id} style={{ display: "flex", gap: 7, fontSize: 11, alignItems: "baseline" }}>
                      <span style={{ width: 5, height: 5, borderRadius: "50%", background: SPEC_TONE[r.p.core], flexShrink: 0 }} />
                      <span style={{ flex: 1 }}>{r.p.name.split(",")[0]}</span>
                      <span style={{ fontFamily: MONO, fontSize: 9.5, color: C.muted }}>{r.p.core}</span>
                      <span style={{ fontFamily: MONO, fontSize: 9.5, width: 70, textAlign: "right", color: r.min <= 60 ? C.ink : C.muted }}>{r.miles} mi · ~{fmtMin(r.min)}</span>
                    </div>
                  ))}
                </div>
              </details>
            </>
          ) : (
            <>
              <div style={{ background: C.surface, border: `1px solid ${C.rule}`, padding: "14px 16px", marginBottom: 12 }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 3 }}>
                  <span style={{ fontFamily: COND, fontSize: 19, fontWeight: 600 }}>{sel}</span>
                  <span style={{ fontFamily: MONO, fontSize: 10.5, color: C.muted }}>{selR.pop}M</span>
                </div>
                <div style={{ fontFamily: MONO, fontSize: 10, color: C.muted, marginBottom: 3 }}>◉ pin at {selR.pin}
                  <button onClick={() => zoomTo(selR.lng, selR.lat, 8)} style={{ background: "none", border: "none", color: C.travel, cursor: "pointer", fontSize: 9.5, fontFamily: MONO, marginLeft: 6 }}>zoom here</button>
                </div>
                <div style={{ fontSize: 11, color: C.muted, marginBottom: 14 }}>{selR.covers}</div>
                <div style={{ display: "flex", alignItems: "baseline", gap: 8, marginBottom: 8, minHeight: 34 }}>
                  <span style={{ fontFamily: COND, fontSize: 30, fontWeight: 600, whiteSpace: "nowrap" }}>{isNoLimit(selLimit) ? "No limit" : selLimit}</span>
                  <span style={{ fontSize: 12, color: C.muted }}>
                    {isNoLimit(selLimit) ? "every provider in the network is listed" : `min · ${Math.round(radiusMiles(sel, selLimit))} mi radius`}
                  </span>
                </div>
                <input type="range" min={RMIN} max={RMAX} step="5" value={isNoLimit(selLimit) ? RMAX : selLimit} disabled={isNoLimit(selLimit)}
                  onChange={(e) => setRadius(sel, parseInt(e.target.value))}
                  style={{ width: "100%", accentColor: C.travel, opacity: isNoLimit(selLimit) ? 0.35 : 1 }} aria-label={`Radius for ${sel} in minutes`} />
                <div style={{ position: "relative", height: 22, margin: "1px 8px 0" }}>
                  {RSTOPS.map((v) => {
                    const pct = ((v - RMIN) / (RMAX - RMIN)) * 100;
                    const on = selLimit === v;
                    return (
                      <button key={v} onClick={() => setRadius(sel, v)} title={`Set ${sel} to ${v} minutes`}
                        style={{ position: "absolute", left: `${pct}%`, transform: "translateX(-50%)", top: 0,
                          background: "none", border: "none", padding: "0 3px", cursor: "pointer",
                          display: "flex", flexDirection: "column", alignItems: "center", gap: 2 }}>
                        <span style={{ width: 1, height: 4, background: on ? C.travel : C.rule }} />
                        <span style={{ fontFamily: MONO, fontSize: 9, color: on ? C.travel : C.muted, fontWeight: on ? 500 : 400 }}>{v}</span>
                      </button>
                    );
                  })}
                </div>
                <button onClick={() => setRadius(sel, isNoLimit(selLimit) ? standard : NOLIMIT)} aria-pressed={isNoLimit(selLimit)}
                  style={{ marginTop: 4, width: "100%", background: isNoLimit(selLimit) ? C.ink : C.surface,
                    color: isNoLimit(selLimit) ? C.surface : C.ink, border: `1px solid ${isNoLimit(selLimit) ? C.ink : C.rule}`,
                    padding: "5px 8px", fontSize: 11, cursor: "pointer", fontFamily: MONO, borderRadius: 0 }}>
                  {isNoLimit(selLimit) ? "← back to a distance limit" : "∞  No limit — show everyone"}
                </button>
                <div style={{ fontSize: 10.5, color: C.muted, marginTop: 8, lineHeight: 1.55, minHeight: 32 }}>
                  {isNoLimit(selLimit) ? "Proximity ignored for this pin. Use when the right specialist matters more than the drive." : `At ${SPEED[sel] || DEFAULT_SPEED} mph effective.`} {overridden
                    ? <>Overrides the {standard}-min standard. <button onClick={() => clearRadius(sel)} style={{ background: "none", border: "none", color: C.travel, cursor: "pointer", padding: 0, fontSize: 10.5, textDecoration: "underline" }}>Reset</button></>
                    : <>Matching the {standard}-min standard.</>}
                </div>
              </div>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 12 }}>
                {CORE.filter((c) => specs.has(c)).map((c) => {
                  const cell = cellFor(sel, c);
                  return (
                    <div key={c} style={{ background: cell.n ? C.ownedBg : C.noneBg, padding: "9px 11px", minHeight: 74, display: "flex", flexDirection: "column" }}>
                      <div style={{ display: "flex", alignItems: "center", gap: 5, marginBottom: 4 }}>
                        <span style={{ width: 6, height: 6, borderRadius: "50%", background: SPEC_TONE[c] }} />
                        <span style={{ fontFamily: MONO, fontSize: 9, letterSpacing: "0.06em", textTransform: "uppercase", color: cell.n ? C.owned : C.none }}>{c}</span>
                      </div>
                      {cell.n === 0 ? <div style={{ fontSize: 11.5, color: C.none }}>Nobody in range</div> : (
                        <>
                          <div style={{ fontFamily: COND, fontSize: 17, fontWeight: 600, color: cell.nearest <= 30 ? C.near : C.owned }}>{cell.n} in range</div>
                          <div style={{ fontSize: 10.5, color: C.muted, marginTop: 2 }}>{cell.hits[0].p.name.split(",")[0]} · ~{fmtMin(cell.nearest)}</div>
                        </>
                      )}
                    </div>
                  );
                })}
              </div>
              <div style={{ background: C.surface, border: `1px solid ${C.rule}`, padding: "10px 12px", minHeight: 132 }}>
                <div style={{ fontFamily: MONO, fontSize: 9, letterSpacing: "0.08em", textTransform: "uppercase", color: C.muted, marginBottom: 7 }}>Who reaches this pin</div>
                {(() => {
                  const all = providers.filter((p) => specs.has(p.core) && reach[p.id] && reach[p.id][sel]).map((p) => ({ p, r: reach[p.id][sel] })).sort((a, b) => a.r.min - b.r.min);
                  if (!all.length) return <div style={{ fontSize: 11.5, color: C.muted }}>Nobody in the selected specialties. Widen the radius, or use No limit to see everyone.</div>;
                  return (
                    <div style={{ display: "flex", flexDirection: "column", gap: 3, maxHeight: 220, overflowY: "auto" }}>
                      {all.map(({ p, r }) => (
                        <button key={p.id} onClick={() => openRecord(p.id)} className="rowhover"
                          title={`Open ${p.name.split(",")[0]}`}
                          style={{ display: "flex", gap: 7, fontSize: 11, alignItems: "baseline", background: "none",
                            border: "none", borderBottom: `1px solid ${C.ruleSoft}`, padding: "3px 2px", cursor: "pointer", textAlign: "left", width: "100%" }}>
                          <span style={{ width: 5, height: 5, borderRadius: "50%", background: SPEC_TONE[p.core], flexShrink: 0 }} />
                          <span style={{ flex: 1, color: C.ink }}>
                            {p.name.split(",")[0]}
                            {p.org && <span style={{ color: C.muted, fontSize: 9.5 }}> · {p.org}</span>}
                          </span>
                          <span style={{ fontFamily: MONO, fontSize: 9.5, color: C.muted }}>{r.city}</span>
                          <span style={{ fontFamily: MONO, fontSize: 9.5, color: r.min <= 30 ? C.near : C.muted, width: 46, textAlign: "right" }}>~{fmtMin(r.min)}</span>
                        </button>
                      ))}
                    </div>
                  );
                })()}
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

function SpecFilter({ specs, setSpecs, providers, activeCore }) {
  const counts = {};
  ALL_SPECS.forEach((c) => (counts[c] = providers.filter((p) => p.core === c && p.sites.length).length));
  return (
    <div style={{ display: "flex", gap: 5, marginTop: 10, flexWrap: "wrap", alignItems: "center" }}>
      <span style={{ fontFamily: MONO, fontSize: 9, letterSpacing: "0.08em", textTransform: "uppercase", color: C.muted, marginRight: 3 }}>Track</span>
      {ALL_SPECS.map((c) => {
        const on = specs.has(c);
        return (
          <button key={c} onClick={() => setSpecs((prev) => { const n = new Set(prev); n.has(c) ? n.delete(c) : n.add(c); return n; })}
            aria-pressed={on}
            style={{ display: "flex", alignItems: "center", gap: 5, background: on ? C.surface : "transparent",
              border: `1px solid ${on ? SPEC_TONE[c] : C.rule}`, color: on ? C.ink : C.muted,
              padding: "4px 9px", fontSize: 11.5, cursor: "pointer", fontFamily: SANS, borderRadius: 0 }}>
            <span style={{ width: 7, height: 7, borderRadius: "50%", background: on ? SPEC_TONE[c] : "transparent", border: on ? "none" : `1px solid ${C.rule}` }} />
            {c}<span style={{ fontFamily: MONO, fontSize: 9, color: C.muted }}>{counts[c]}</span>
          </button>
        );
      })}
      <button onClick={() => setSpecs(new Set(CORE))} style={{ background: "none", border: "none", color: C.travel, fontSize: 10.5, cursor: "pointer" }}>core four</button>
      <span style={{ fontSize: 10.5, color: C.muted, marginLeft: 4 }}>
        {activeCore.length === 0 ? "Nothing tracked — the ledger and counts are empty." :
         activeCore.length === 4 ? "Counting all four core specialties everywhere." :
         `Ledger, map, and counts cover ${activeCore.join(", ")} only.`}
      </span>
    </div>
  );
}

function AccountMenu({ me }) {
  const [open, setOpen] = useState(false);
  const [pw, setPw] = useState({ current: "", next: "" });
  const [msg, setMsg] = useState(null);
  const logout = async () => { try { await api("POST", "/api/auth/logout"); } catch (e) {} window.location.href = "/"; };
  const change = async () => {
    setMsg(null);
    try { await api("POST", "/api/auth/password", pw); setMsg({ ok: true, t: "Password changed." }); setPw({ current: "", next: "" }); }
    catch (e) { setMsg({ ok: false, t: e.message }); }
  };
  return (
    <div style={{ position: "relative" }}>
      <button onClick={() => setOpen(!open)} style={{ display: "flex", alignItems: "center", gap: 6, background: "none",
        border: `1px solid ${C.rule}`, padding: "4px 9px", cursor: "pointer", fontFamily: MONO, fontSize: 10, color: C.ink, borderRadius: 0 }}>
        <span style={{ width: 6, height: 6, borderRadius: "50%", background: C.owned }} />
        {me.name}{me.role === "admin" ? " · admin" : ""} ▾
      </button>
      {open && (
        <div style={{ position: "absolute", right: 0, top: "calc(100% + 4px)", background: C.surface, border: `1px solid ${C.rule}`,
          padding: 12, width: 232, zIndex: 50, boxShadow: "0 4px 16px rgba(0,0,0,0.08)" }}>
          <div style={{ fontSize: 11, color: C.muted, marginBottom: 10 }}>{me.email}</div>
          <div style={{ fontFamily: MONO, fontSize: 9, letterSpacing: "0.08em", textTransform: "uppercase", color: C.muted, marginBottom: 6 }}>Change password</div>
          <input type="password" placeholder="current" value={pw.current} onChange={(e) => setPw({ ...pw, current: e.target.value })}
            style={{ ...inp, fontSize: 11, padding: "5px 7px", width: "100%", marginBottom: 5 }} />
          <input type="password" placeholder="new (8+ chars)" value={pw.next} onChange={(e) => setPw({ ...pw, next: e.target.value })}
            style={{ ...inp, fontSize: 11, padding: "5px 7px", width: "100%", marginBottom: 8 }} />
          <button onClick={change} disabled={!pw.current || pw.next.length < 8}
            style={{ ...btn, fontSize: 11, width: "100%", opacity: (!pw.current || pw.next.length < 8) ? 0.4 : 1 }}>Update</button>
          {msg && <div style={{ fontSize: 10.5, marginTop: 7, color: msg.ok ? C.owned : C.none }}>{msg.t}</div>}
          <div style={{ borderTop: `1px solid ${C.ruleSoft}`, margin: "11px 0 9px" }} />
          <button onClick={logout} style={{ background: "none", border: `1px solid ${C.rule}`, width: "100%", padding: "6px", fontSize: 11.5, cursor: "pointer", fontFamily: SANS, color: C.ink }}>Sign out</button>
        </div>
      )}
    </div>
  );
}

function Kpi({ label, value, sub, tone }) {
  return (
    <div style={{ background: C.surface, padding: "12px 14px" }}>
      <div style={{ fontFamily: MONO, fontSize: 9, letterSpacing: "0.08em", textTransform: "uppercase", color: C.muted, marginBottom: 6 }}>{label}</div>
      <div style={{ fontFamily: COND, fontSize: 25, fontWeight: 600, lineHeight: 1, color: tone || C.ink }}>{value}</div>
      <div style={{ fontSize: 10.5, color: C.muted, marginTop: 4 }}>{sub}</div>
    </div>
  );
}

function Ledger({ cellFor, targets, setTarget, setAllTargets, standard, setStandard, openRegion, setOpenRegion, limitFor, activeCore }) {
  const COLS = activeCore;
  const grid = `216px 46px repeat(${Math.max(COLS.length, 1)},1fr) 74px`;
  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", gap: 9, marginBottom: 10, flexWrap: "wrap" }}>
        <span style={{ fontFamily: MONO, fontSize: 9.5, letterSpacing: "0.09em", textTransform: "uppercase", color: C.muted }}>Coverage standard</span>
        {[30, 45, 60, NOLIMIT].map((v) => (
          <button key={v} onClick={() => setStandard(v)} style={{
            background: standard === v ? C.ink : C.surface, color: standard === v ? C.surface : C.ink,
            border: `1px solid ${standard === v ? C.ink : C.rule}`, padding: "5px 12px", fontSize: 11.5,
            cursor: "pointer", fontFamily: MONO, borderRadius: 0,
          }}>{isNoLimit(v) ? "No limit" : `${v} min`}</button>
        ))}
        <span style={{ fontSize: 11, color: C.muted }}>
          {isNoLimit(standard) ? "Distance ignored — every provider counts everywhere." : "drive time from the pin"}
        </span>
        <div style={{ flex: 1 }} />
        <span style={{ fontFamily: MONO, fontSize: 9.5, letterSpacing: "0.09em", textTransform: "uppercase", color: C.muted }}>Depth</span>
        {[1, 2].map((v) => {
          const on = Object.values(targets).length > 0 && Object.values(targets).every((t) => t === v);
          return (
            <button key={v} onClick={() => setAllTargets(v)} aria-pressed={on} style={{
              background: on ? C.ink : C.surface, color: on ? C.surface : C.ink,
              border: `1px solid ${on ? C.ink : C.rule}`, padding: "5px 10px",
              fontSize: 11.5, cursor: "pointer", fontFamily: MONO, borderRadius: 0,
            }}>{v}</button>
          );
        })}
        <span style={{ fontSize: 10.5, color: C.muted }}>providers wanted per cell</span>
      </div>

      <p style={{ fontSize: 12.5, color: C.muted, margin: "0 0 8px", maxWidth: 660, lineHeight: 1.65 }}>
        Each region has a pin at its heart. A cell is covered if a provider can reach that pin inside the standard.
        Regions run north to south. Click a cell to see who reaches it and how long it takes them.
      </p>
      <details style={{ marginBottom: 14, maxWidth: 660 }}>
        <summary style={{ fontSize: 11.5, color: C.travel, cursor: "pointer" }}>How drive time is estimated</summary>
        <div style={{ fontSize: 11.5, color: C.muted, lineHeight: 1.7, marginTop: 7, background: C.surface, border: `1px solid ${C.rule}`, padding: "10px 12px" }}>
          Straight-line distance from the provider's city to the pin, multiplied by 1.27 for road routing, divided by
          an effective door-to-door speed that varies by region — 30 mph in the LA Basin, 48 mph in open country.
          It is an estimate, not a routed time, and it does not know about rush hour, the Grapevine, or a provider
          who happens to live on the right side of town. Treat anything within a few minutes of the threshold as a
          judgment call, and verify before you promise it to a carrier.
          <br /><br />
          A provider covers every pin they can reach, so one physician can serve several regions. Nobody is assigned
          to a region by label anymore — only by distance.
        </div>
      </details>

      {COLS.length === 0 && <div style={{ background: C.surface, border: `1px solid ${C.rule}`, padding: 30, textAlign: "center", fontSize: 12.5, color: C.muted }}>No specialties tracked. Use the Track chips above to choose what the ledger measures.</div>}
      {COLS.length > 0 && <div style={{ background: C.surface, border: `1px solid ${C.rule}` }}>
        <div style={{ display: "grid", gridTemplateColumns: grid, background: C.ground, borderBottom: `1px solid ${C.rule}` }}>
          <div style={hcell}>Region · pin</div>
          <div style={{ ...hcell, textAlign: "right" }}>Pop</div>
          {COLS.map((c) => <div key={c} style={{ ...hcell, textAlign: "center" }}>{c}</div>)}
          <div style={{ ...hcell, textAlign: "right" }}>Short</div>
        </div>

        {REGIONS.map((r, i) => {
          const open = openRegion === r.name;
          const cells = COLS.map((c) => cellFor(r.name, c));
          const gaps = cells.filter((c) => c.n === 0).length;
          const shortCells = cells.filter((c, j) => c.n < (targets[r.name + "|" + COLS[j]] || 0)).length;
          return (
            <div key={r.name}>
              <div style={{ display: "grid", gridTemplateColumns: grid, borderBottom: `1px solid ${open ? C.rule : C.ruleSoft}`, background: open ? "#F7F9F8" : C.surface }}>
                <div style={{ padding: "8px 12px", display: "flex", alignItems: "center", gap: 6 }}>
                  <span style={{ fontFamily: MONO, fontSize: 9, color: C.muted, width: 13 }}>{String(i + 1).padStart(2, "0")}</span>
                  <span>
                    <span style={{ fontFamily: COND, fontSize: 14.5, fontWeight: 600 }}>{r.name}</span>
                    <span style={{ display: "block", fontFamily: MONO, fontSize: 9, color: C.muted }}>◉ {r.pin}</span>
                  </span>
                  {r.fly ? <span title="Fly-in corridor" style={{ fontFamily: MONO, fontSize: 8, color: C.travel, background: C.travelBg, padding: "2px 3px" }}>FLY</span> : null}
                </div>
                <div style={{ padding: "8px 6px", fontFamily: MONO, fontSize: 11, color: C.muted, textAlign: "right", alignSelf: "center" }}>{r.pop}M</div>
                {COLS.map((c, j) => <Cell key={c} cell={cells[j]} target={targets[r.name + "|" + c] || 0} onOpen={() => setOpenRegion(open ? null : r.name)} />)}
                <div style={{ padding: "8px 12px", alignSelf: "center", textAlign: "right", fontFamily: MONO, fontSize: 13, fontWeight: 500,
                  color: shortCells === 0 ? C.owned : gaps > 0 ? (r.fly ? C.travel : C.none) : C.flag }}
                  title={gaps > 0 ? `${gaps} with nobody at all` : shortCells > 0 ? `${shortCells} below depth` : "meets target"}>
                  {shortCells === 0 ? "✓" : shortCells}
                </div>
              </div>
              {open && <RegionDetail region={r} cellFor={cellFor} targets={targets} setTarget={setTarget} standard={standard} cols={COLS} />}
            </div>
          );
        })}
      </div>}

      <div style={{ display: "flex", gap: 15, flexWrap: "wrap", marginTop: 12, fontSize: 11, color: C.muted, alignItems: "center" }}>
        <Legend color={C.near} label="≤30 min — ideal" />
        <Legend color={C.owned} label="Standing office in range" />
        <Legend color={C.travel} label="Fly-in only" />
        <Legend color={C.none} label="Nobody in range" />
      </div>
    </div>
  );
}

function Legend({ color, label }) {
  return <span style={{ display: "flex", alignItems: "center", gap: 5 }}><span style={{ width: 8, height: 8, background: color, borderRadius: "50%" }} />{label}</span>;
}

function Cell({ cell, target, onOpen }) {
  const { n, nearest, allTravel } = cell;
  const short = Math.max(0, target - n);
  const bg = n === 0 ? C.noneBg : short > 0 ? C.flagBg : allTravel ? C.travelBg : C.ownedBg;
  const fg = n === 0 ? C.none : short > 0 ? C.flag : allTravel ? C.travel : nearest <= 30 ? C.near : C.owned;
  return (
    <button onClick={onOpen} className="rowhover" title={n === 0 ? `Nobody in range (want ${target})` : short > 0 ? `${n} in range, want ${target} — ${short} short · nearest ~${fmtMin(nearest)}` : `${n} in range · nearest ~${fmtMin(nearest)}`}
      style={{ background: bg, border: "none", borderRight: `1px solid ${C.ground}`, cursor: "pointer", padding: "7px 4px", textAlign: "center", width: "100%", minHeight: 46 }}>
      <div style={{ fontFamily: MONO, fontSize: 14.5, fontWeight: 500, color: fg, lineHeight: 1 }}>{n === 0 ? "—" : n}</div>
      <div style={{ fontFamily: MONO, fontSize: 8.5, color: fg, marginTop: 3, opacity: 0.85 }}>
        {n === 0 ? " " : `~${fmtMin(nearest)}`}
      </div>
      <div style={{ display: "flex", gap: 2, justifyContent: "center", marginTop: 3, minHeight: 4 }}>
        {Array.from({ length: Math.min(short, 4) }).map((_, i) => (
          <span key={i} style={{ width: 4, height: 4, border: `1px solid ${n === 0 ? C.none : C.flag}`, borderRadius: "50%", opacity: 0.6 }} />
        ))}
      </div>
    </button>
  );
}

function RegionDetail({ region, cellFor, targets, setTarget, standard, cols }) {
  return (
    <div style={{ background: "#F7F9F8", borderBottom: `1px solid ${C.rule}`, padding: "14px 16px 18px" }}>
      <div style={{ fontSize: 12, color: C.muted, marginBottom: 12 }}>
        Pin at <strong style={{ color: C.ink, fontWeight: 500 }}>{region.pin}</strong> · serves {region.covers}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(238px,1fr))", gap: 12 }}>
        {cols.map((c) => {
          const cell = cellFor(region.name, c);
          const tgt = targets[region.name + "|" + c] || 0;
          return (
            <div key={c} style={{ background: C.surface, border: `1px solid ${C.rule}`, padding: "10px 12px" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                <span style={{ fontFamily: COND, fontSize: 13.5, fontWeight: 600 }}>{c}</span>
                <label style={{ fontFamily: MONO, fontSize: 10, color: C.muted, display: "flex", alignItems: "center", gap: 5 }}>
                  target
                  <input type="number" min="0" value={tgt} onChange={(e) => setTarget(region.name, c, e.target.value)}
                    style={{ width: 38, padding: "2px 4px", border: `1px solid ${C.rule}`, fontFamily: MONO, fontSize: 11, background: C.surface, color: C.ink }} />
                </label>
              </div>
              {cell.n === 0 ? (
                <div style={{ fontSize: 11.5, color: C.none, background: C.noneBg, padding: "6px 8px" }}>
                  {isNoLimit(standard) ? `Nobody in the network at all.` : `Nobody within ${standard} min of ${region.pin}.`}
                </div>
              ) : (
                <ul style={{ margin: 0, padding: 0, listStyle: "none" }}>
                  {cell.hits.map(({ p, r }) => (
                    <li key={p.id} style={{ display: "flex", gap: 7, alignItems: "flex-start", padding: "3px 0", fontSize: 11.5, lineHeight: 1.45 }}>
                      <span style={{ width: 5, height: 5, borderRadius: "50%", background: r.type === "travel" ? C.travel : r.min <= 30 ? C.near : C.owned, marginTop: 5, flexShrink: 0 }} />
                      <span>
                        {p.name.split(",")[0]}
                        {p.qme && <span style={{ fontFamily: MONO, fontSize: 8, color: C.travel, marginLeft: 4 }}>QME</span>}
                        <span style={{ color: C.muted, display: "block", fontSize: 10.5, fontFamily: MONO }}>
                          {r.city} · {r.miles} mi · ~{fmtMin(r.min)}{r.type === "travel" ? " · fly-in" : ""}
                        </span>
                      </span>
                    </li>
                  ))}
                </ul>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

function ConfBadge({ conf }) {
  const map = {
    documented: [C.owned, C.ownedBg, "Confirmed"], confirmed: [C.owned, C.ownedBg, "Confirmed"],
    assumed: [C.muted, "#EDF0EF", "Assumed"], needs_confirm: [C.flag, C.flagBg, "Confirm"],
    out_of_state: [C.none, C.noneBg, "Out of state"],
  };
  const [fg, bg, label] = map[conf] || map.assumed;
  return <span style={{ fontFamily: MONO, fontSize: 8.5, color: fg, background: bg, padding: "2px 5px", letterSpacing: "0.05em", textTransform: "uppercase" }}>{label}</span>;
}

async function apiUpload(path, file, fields) {
  const fd = new FormData();
  fd.set("file", file);
  Object.entries(fields).forEach(([k, v]) => v && fd.set(k, v));
  const res = await fetch(path, { method: "POST", headers: { "x-actor": getActor() || "unknown" }, body: fd });
  if (!res.ok) throw new Error((await res.json().catch(() => ({}))).error || "upload failed");
  return res.json();
}

const Section = ({ title, count, action, children }) => (
  <section style={{ marginBottom: 16 }}>
    <div style={{ display: "flex", alignItems: "center", gap: 7, marginBottom: 7 }}>
      <h3 style={{ fontFamily: MONO, fontSize: 9, letterSpacing: "0.09em", textTransform: "uppercase", color: C.muted, margin: 0, fontWeight: 400 }}>{title}</h3>
      {count != null && <span style={{ fontFamily: MONO, fontSize: 9, color: C.muted, opacity: 0.7 }}>{count}</span>}
      <div style={{ flex: 1, height: 1, background: C.ruleSoft }} />
      {action}
    </div>
    {children}
  </section>
);
const Empty = ({ children }) => <div style={{ fontSize: 11.5, color: C.muted, padding: "8px 0", fontStyle: "italic" }}>{children}</div>;
const linkBtn = { background: "none", border: "none", color: C.travel, fontSize: 10.5, cursor: "pointer", padding: 0, fontFamily: SANS };

// ---------------------------------------------------------------------------
// Providers — master/detail. The list is how you work; the record is what you
// work on. A full-page record would lose your place on every provider.
// ---------------------------------------------------------------------------
function Providers({ providers, reload, actor, specs, reach, standard, openProvider, setOpenProvider }) {
  const [sel, setSel] = useState(null);
  // Arriving from the map: select that provider and clear the hand-off.
  useEffect(() => { if (openProvider) { setSel(openProvider); setOpenProvider(null); } }, [openProvider]);
  const [q, setQ] = useState("");
  const [fCore, setFCore] = useState("all");
  const [fConf, setFConf] = useState("all");

  const list = providers.filter((p) => {
    if (q && !(p.name + p.specialty + p.detail).toLowerCase().includes(q.toLowerCase())) return false;
    if (fCore !== "all" && p.core !== fCore) return false;
    if (fConf !== "all" && p.conf !== fConf) return false;
    return true;
  });
  useEffect(() => { if (!sel && list.length) setSel(list[0].id); }, [list, sel]);

  return (
    <div style={{ display: "flex", gap: 0, border: `1px solid ${C.rule}`, background: C.surface, alignItems: "stretch", minHeight: 560 }}>
      <div style={{ width: 272, borderRight: `1px solid ${C.rule}`, display: "flex", flexDirection: "column", flexShrink: 0 }}>
        <div style={{ padding: 9, borderBottom: `1px solid ${C.ruleSoft}`, display: "flex", flexDirection: "column", gap: 6 }}>
          <input value={q} onChange={(e) => setQ(e.target.value)} placeholder={`Search ${providers.length} providers`}
            style={{ ...inp, fontSize: 12, padding: "6px 8px" }} />
          <div style={{ display: "flex", gap: 5 }}>
            <select value={fCore} onChange={(e) => setFCore(e.target.value)} style={{ ...inp, fontSize: 11, padding: "4px 5px", flex: 1 }}>
              <option value="all">All specialties</option>
              {ALL_SPECS.map((c) => <option key={c}>{c}</option>)}
            </select>
            <select value={fConf} onChange={(e) => setFConf(e.target.value)} style={{ ...inp, fontSize: 11, padding: "4px 5px", flex: 1 }}>
              <option value="all">Any status</option>
              <option value="documented">Confirmed</option>
              <option value="assumed">Assumed</option>
              <option value="needs_confirm">Needs confirming</option>
            </select>
          </div>
        </div>
        <div style={{ flex: 1, overflowY: "auto", maxHeight: 620 }}>
          {list.length === 0 && <Empty>Nothing matches those filters.</Empty>}
          {list.map((p) => {
            const on = p.id === sel;
            return (
              <button key={p.id} onClick={() => setSel(p.id)} className="rowhover"
                style={{ display: "block", width: "100%", textAlign: "left", background: on ? "#EAEEED" : "transparent",
                  border: "none", borderLeft: `2px solid ${on ? SPEC_TONE[p.core] : "transparent"}`,
                  borderBottom: `1px solid ${C.ruleSoft}`, padding: "8px 10px", cursor: "pointer" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                  <span style={{ width: 6, height: 6, borderRadius: "50%", background: SPEC_TONE[p.core], flexShrink: 0 }} />
                  <span style={{ fontSize: 12, fontWeight: on ? 600 : 400, color: C.ink, flex: 1, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                    {p.name.split(",")[0]}
                  </span>
                  {p.qme && <span style={{ fontFamily: MONO, fontSize: 7.5, color: C.travel }}>QME</span>}
                </div>
                {p.org && <div style={{ fontSize: 9.5, color: C.muted, paddingLeft: 12, marginTop: 1, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{p.org}</div>}
                <div style={{ display: "flex", gap: 5, marginTop: 3, alignItems: "center", paddingLeft: 12 }}>
                  <span style={{ fontFamily: MONO, fontSize: 9, color: C.muted }}>
                    {p.sites.length ? `${p.sites.length} site${p.sites.length > 1 ? "s" : ""}` : "no location"}
                  </span>
                  <span style={{ width: 5, height: 5, borderRadius: "50%", flexShrink: 0,
                    background: p.conf === "documented" ? C.owned : p.conf === "needs_confirm" ? C.flag : p.conf === "out_of_state" ? C.none : C.rule }} />
                  {p.travel === "anywhere" && <span title="Travels anywhere" style={{ fontFamily: MONO, fontSize: 7.5, color: C.travel }}>✈ any</span>}
                  {p.travel === "radius" && <span title={`Travels ${p.travelRadius} mi`} style={{ fontFamily: MONO, fontSize: 7.5, color: C.travel }}>✈ {p.travelRadius}mi</span>}
                </div>
              </button>
            );
          })}
        </div>
      </div>
      <div style={{ flex: 1, minWidth: 0 }}>
        {sel ? <ProviderRecord key={sel} id={sel} reload={reload} actor={actor} reach={reach} standard={standard} />
             : <div style={{ padding: 40, color: C.muted, fontSize: 12.5 }}>Select a provider.</div>}
      </div>
    </div>
  );
}

function ProviderRecord({ id, reload, actor, reach, standard }) {
  const [d, setD] = useState(null);
  const [contacts, setContacts] = useState({ people: [], methods: [], unattached: [] });
  const [corr, setCorr] = useState([]);
  const [busy, setBusy] = useState(false);
  const [oops, setOops] = useState(null);

  const fetchAll = async () => {
    try {
      const [phys, c, cor] = await Promise.all([
        api("GET", `/api/physicians/${id}`),
        api("GET", `/api/physicians/${id}/contacts`),
        api("GET", `/api/physicians/${id}/correspondence`),
      ]);
      setD(phys); setContacts(c); setCorr(cor); setOops(null);
    } catch (e) { setOops(e.message); }
  };
  useEffect(() => { fetchAll(); }, [id]);
  const act = async (fn) => {
    setBusy(true);
    try { await fn(); await fetchAll(); await reload(); setOops(null); }
    catch (e) { setOops(e.message); }
    finally { setBusy(false); }
  };

  if (oops && !d) return <div style={{ padding: 30, color: C.none, fontSize: 12.5 }}>{oops}</div>;
  if (!d) return <div style={{ padding: 30, color: C.muted, fontFamily: MONO, fontSize: 11.5 }}>Loading record…</div>;

  const locs = d.locations.filter((l) => l.is_active);
  const confirmed = locs.filter((l) => l.confirmation_status === "confirmed").length;
  // The record's first sentence: what can you actually stand behind?
  const tmode = (d.travel || {}).mode || "none";
  const travelLine = tmode === "anywhere" ? " Travels anywhere, so they reach every pin."
    : tmode === "radius" ? ` Travels up to ${d.travel.radius_miles} mi from any site.`
    : tmode === "listed" ? " Travels to the fly-in places listed."
    : "";
  const trust = locs.length === 0
    ? { tone: C.none, bg: C.noneBg, text: "No location on file — this provider is invisible to the map and the ledger." }
    : confirmed === locs.length
    ? { tone: C.owned, bg: C.ownedBg, text: `${locs.length} site${locs.length > 1 ? "s" : ""} confirmed directly with the provider. Safe to claim.` }
    : confirmed === 0
    ? { tone: C.flag, bg: C.flagBg, text: `${locs.length} site${locs.length > 1 ? "s" : ""}, none confirmed — inferred from the source export, never verified with the provider.` }
    : { tone: C.flag, bg: C.flagBg, text: `${locs.length} sites, ${confirmed} confirmed. The remaining ${locs.length - confirmed} are inferred, not verified.` };
  trust.text += travelLine;

  return (
    <div style={{ padding: "16px 18px 26px", opacity: busy ? 0.65 : 1, transition: "opacity .12s" }}>
      {oops && <div style={{ background: C.noneBg, color: C.none, padding: "7px 10px", fontSize: 11.5, marginBottom: 10 }}>{oops}</div>}

      <header style={{ marginBottom: 12 }}>
        <div style={{ display: "flex", alignItems: "baseline", gap: 8, flexWrap: "wrap" }}>
          <h2 style={{ fontFamily: COND, fontSize: 24, fontWeight: 600, margin: 0 }}>{d.full_name}</h2>
          {d.credentials && <span style={{ fontFamily: MONO, fontSize: 11, color: C.muted }}>{d.credentials}</span>}
          {d.is_qme ? <span style={{ fontFamily: MONO, fontSize: 8.5, color: C.travel, background: C.travelBg, padding: "2px 5px" }}>QME</span> : null}
          <div style={{ flex: 1 }} />
          {d.preference && <span style={{ fontFamily: MONO, fontSize: 9, color: C.muted, border: `1px solid ${C.rule}`, padding: "2px 5px" }}>{d.preference}</span>}
        </div>
        <div style={{ display: "flex", gap: 7, alignItems: "center", marginTop: 5, flexWrap: "wrap" }}>
          <span style={{ width: 7, height: 7, borderRadius: "50%", background: SPEC_TONE[CORE_FROM_CODE[d.specialty_code]] || C.muted }} />
          <span style={{ fontSize: 11.5, color: C.muted }}>{d.specialty_detail || d.specialty_code}</span>
        </div>
        <div style={{ display: "flex", gap: 7, alignItems: "center", marginTop: 4, flexWrap: "wrap" }}>
          {d.organization ? (
            <>
              <span style={{ fontFamily: MONO, fontSize: 8, color: C.muted, letterSpacing: "0.06em" }}>{d.organization.kind.replace("_", " ").toUpperCase()}</span>
              <span style={{ fontSize: 12, fontWeight: 500 }}>{d.organization.name}</span>
              {d.colleagues.length > 0 && (
                <span style={{ fontSize: 10.5, color: C.muted }}>
                  with {d.colleagues.map((c) => c.full_name.split(",")[0]).join(", ")}
                </span>
              )}
            </>
          ) : <span style={{ fontFamily: MONO, fontSize: 9, color: C.muted }}>INDEPENDENT</span>}
        </div>
      </header>

      <div style={{ background: trust.bg, borderLeft: `3px solid ${trust.tone}`, padding: "8px 11px", marginBottom: 16 }}>
        <div style={{ fontFamily: MONO, fontSize: 8.5, letterSpacing: "0.08em", textTransform: "uppercase", color: trust.tone, marginBottom: 2 }}>Coverage claim</div>
        <div style={{ fontSize: 12, color: C.ink }}>{trust.text}</div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "minmax(0,1.35fr) minmax(0,1fr)", gap: 22 }}>
        <div style={{ minWidth: 0 }}>
          <LocationsPanel d={d} locs={locs} act={act} />
          <TravelPanel d={d} act={act} />
          <CorrespondencePanel d={d} corr={corr} contacts={contacts} act={act} actor={actor} />
        </div>
        <div style={{ minWidth: 0 }}>
          <ContactsPanel d={d} contacts={contacts} act={act} />
          <DocumentsPanel d={d} act={act} />
          <FeesPanel d={d} act={act} />
        </div>
      </div>
    </div>
  );
}

function TravelPanel({ d, act }) {
  const t = d.travel || { mode: "none" };
  const [radius, setRadius] = useState(t.radius_miles || 60);
  const MODES = [
    ["none", "Their offices only", "Won't travel. Only the sites below count."],
    ["listed", "Only these fly-in places", "Will travel, but only to the places listed below."],
    ["radius", "Anywhere within a radius", "Will travel this far from any of their sites."],
    ["anywhere", "Anywhere in California", "Covers every pin, however far."],
  ];
  return (
    <Section title="Will they travel?">
      <div style={{ display: "flex", flexDirection: "column", gap: 3 }}>
        {MODES.map(([m, label, help]) => {
          const on = t.mode === m;
          return (
            <button key={m} onClick={() => act(() => api("PUT", `/api/physicians/${d.id}/travel`, { mode: m, radius_miles: m === "radius" ? radius : null }))}
              style={{ display: "flex", gap: 8, alignItems: "flex-start", textAlign: "left", width: "100%", cursor: "pointer",
                background: on ? C.travelBg : "transparent", border: `1px solid ${on ? C.travel : C.ruleSoft}`, padding: "6px 8px" }}>
              <span style={{ width: 9, height: 9, borderRadius: "50%", border: `1px solid ${on ? C.travel : C.rule}`,
                background: on ? C.travel : "transparent", marginTop: 2, flexShrink: 0 }} />
              <span style={{ flex: 1 }}>
                <span style={{ fontSize: 11.5, fontWeight: on ? 600 : 400, color: C.ink }}>{label}</span>
                <span style={{ display: "block", fontSize: 10, color: C.muted, marginTop: 1 }}>{help}</span>
              </span>
            </button>
          );
        })}
      </div>
      {t.mode === "radius" && (
        <div style={{ display: "flex", gap: 6, alignItems: "center", marginTop: 6 }}>
          <input type="number" min="5" max="400" value={radius} onChange={(e) => setRadius(+e.target.value)}
            style={{ ...inp, fontSize: 11.5, padding: "4px 6px", width: 66 }} />
          <span style={{ fontSize: 11, color: C.muted, flex: 1 }}>miles from any of their sites</span>
          <button onClick={() => act(() => api("PUT", `/api/physicians/${d.id}/travel`, { mode: "radius", radius_miles: radius }))}
            style={{ ...btn, fontSize: 10.5, padding: "4px 8px" }}>Save</button>
        </div>
      )}
      <div style={{ fontSize: 10, color: t.confirmed_at ? C.owned : C.flag, marginTop: 6 }}>
        {t.confirmed_at ? `Confirmed by ${t.confirmed_by} · ${(t.confirmed_at || "").slice(0, 10)}`
          : "Not confirmed with the provider — the map assumes the conservative answer."}
      </div>
    </Section>
  );
}

function LocationsPanel({ d, locs, act }) {
  const [city, setCity] = useState("");
  const [type, setType] = useState("office");
  return (
    <Section title="Where they sit" count={locs.length}>
      {locs.length === 0 && <Empty>Nothing on file. Until a location exists, this provider covers no pin.</Empty>}
      <div style={{ display: "flex", flexDirection: "column", gap: 4, marginBottom: 8 }}>
        {locs.map((l) => (
          <div key={l.id} style={{ border: `1px solid ${C.rule}`, borderLeft: `3px solid ${l.site_type === "flyin" ? C.travel : C.owned}`, padding: "7px 9px" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 7 }}>
              <span style={{ fontSize: 12.5, fontWeight: 500, flex: 1, minWidth: 0 }}>
                {l.address_line || l.city}
                {l.address_line && <span style={{ color: C.muted, fontWeight: 400 }}> · {l.city}</span>}
                {l.organization_name && <span style={{ display: "block", fontSize: 9.5, color: C.muted, fontWeight: 400 }}>{l.organization_name}</span>}
              </span>
              <span style={{ fontFamily: MONO, fontSize: 8.5, color: l.site_type === "flyin" ? C.travel : C.owned }}>
                {l.site_type === "flyin" ? "FLY-IN" : "OFFICE"}
              </span>
              <ConfBadge conf={l.confirmation_status} />
              <button onClick={() => act(() => api("DELETE", `/api/locations/${l.id}`))}
                style={{ background: "none", border: "none", color: C.muted, cursor: "pointer", fontSize: 14, lineHeight: 1, padding: "0 2px" }} aria-label={`Remove ${l.city}`}>×</button>
            </div>
            <div style={{ display: "flex", gap: 8, alignItems: "center", marginTop: 4 }}>
              <span style={{ fontFamily: MONO, fontSize: 9, color: l.lat == null ? C.none : C.muted }}>
                {l.lat == null ? "NO COORDINATES — cannot be measured" : `${l.lat.toFixed(3)}, ${l.lng.toFixed(3)} · ${l.geocode_source.replace("_", " ")}`}
              </span>
              {l.site_physician_count > 1 && (
                <span title="Editing this address changes it for everyone who sits here"
                  style={{ fontFamily: MONO, fontSize: 8, color: C.travel, background: C.travelBg, padding: "1px 4px" }}>
                  SHARED · {l.site_physician_count} physicians
                </span>
              )}
              <div style={{ flex: 1 }} />
              {l.confirmation_status !== "confirmed" ? (
                <button onClick={() => act(() => api("PATCH", `/api/locations/${l.id}`, { confirmation_status: "confirmed" }))} style={linkBtn}>
                  confirm with provider
                </button>
              ) : (
                <span style={{ fontFamily: MONO, fontSize: 9, color: C.owned }}>
                  {l.confirmed_by} · {(l.confirmed_at || "").slice(0, 10)}
                </span>
              )}
              <button onClick={() => act(() => api("PATCH", `/api/locations/${l.id}`, { site_type: l.site_type === "flyin" ? "office" : "flyin" }))} style={linkBtn}>
                {l.site_type === "flyin" ? "→ office" : "→ fly-in"}
              </button>
            </div>
          </div>
        ))}
      </div>
      <div style={{ display: "flex", gap: 5 }}>
        <input list="ca-places" value={city} onChange={(e) => setCity(e.target.value)} placeholder="City or ZIP"
          style={{ ...inp, fontSize: 11.5, padding: "5px 7px", flex: 1 }} />
        <select value={type} onChange={(e) => setType(e.target.value)} style={{ ...inp, fontSize: 11.5, padding: "5px 7px" }}>
          <option value="office">Standing office</option>
          <option value="flyin">Fly-in / rented</option>
        </select>
        <button disabled={!city.trim()} onClick={() => { act(() => api("POST", `/api/physicians/${d.id}/locations`, { city: city.trim(), site_type: type })); setCity(""); }}
          style={{ ...btn, opacity: city.trim() ? 1 : 0.4 }}>Add</button>
      </div>
    </Section>
  );
}

function ContactsPanel({ d, contacts, act }) {
  const [open, setOpen] = useState(false);
  const [f, setF] = useState({ kind: "phone", value: "", purpose: "scheduling", contact_person_id: "" });
  const [pf, setPf] = useState({ name: "", role: "" });
  const href = (m) => m.kind === "email" ? `mailto:${m.value_normalized || m.value}`
    : m.kind === "phone" || m.kind === "fax" ? `tel:${m.value_normalized || m.value}`
    : (m.value_normalized || m.value);
  const Method = ({ m }) => (
    <div style={{ display: "flex", gap: 6, alignItems: "baseline", padding: "2px 0" }}>
      <span style={{ fontFamily: MONO, fontSize: 8, color: C.muted, width: 40, flexShrink: 0, textTransform: "uppercase" }}>{m.purpose === "general" ? m.kind : m.purpose}</span>
      <a href={href(m)} target={m.kind === "website" ? "_blank" : undefined} rel="noreferrer"
        style={{ fontSize: 11.5, color: C.ink, textDecoration: "none", borderBottom: `1px dotted ${C.rule}`, flex: 1, wordBreak: "break-all" }}>
        {m.value}
      </a>
      {m.is_primary ? <span style={{ fontFamily: MONO, fontSize: 7.5, color: C.owned }}>1°</span> : null}
      {m.verified_at
        ? <span title={`verified by ${m.verified_by}`} style={{ color: C.owned, fontSize: 10 }}>✓</span>
        : <button onClick={() => act(() => api("PATCH", `/api/contacts/methods/${m.id}`, { verified: true }))}
            title="Mark verified" style={{ ...linkBtn, fontSize: 9.5 }}>verify</button>}
    </div>
  );
  return (
    <Section title="Who to call" count={contacts.methods.length}
      action={<button onClick={() => setOpen(!open)} style={linkBtn}>{open ? "close" : "+ add"}</button>}>
      {contacts.people.map((p) => (
        <div key={p.id} style={{ marginBottom: 8 }}>
          <div style={{ display: "flex", gap: 6, alignItems: "baseline" }}>
            <span style={{ fontSize: 12, fontWeight: 500 }}>{p.name}</span>
            {p.role && <span style={{ fontFamily: MONO, fontSize: 9, color: C.muted }}>{p.role}</span>}
            {p.is_primary ? <span style={{ fontFamily: MONO, fontSize: 7.5, color: C.owned }}>PRIMARY</span> : null}
          </div>
          <div style={{ paddingLeft: 2, borderLeft: `1px solid ${C.ruleSoft}`, marginLeft: 1, paddingTop: 2 }}>
            {p.methods.map((m) => <Method key={m.id} m={m} />)}
          </div>
        </div>
      ))}
      {contacts.unattached.length > 0 && (
        <div style={{ marginBottom: 8 }}>
          {contacts.people.length > 0 && <div style={{ fontFamily: MONO, fontSize: 8, color: C.muted, marginBottom: 2 }}>PRACTICE</div>}
          {contacts.unattached.map((m) => <Method key={m.id} m={m} />)}
        </div>
      )}
      {contacts.methods.length === 0 && <Empty>No contact details on file.</Empty>}

      {open && (
        <div style={{ background: "#F7F9F8", border: `1px solid ${C.rule}`, padding: 9, marginTop: 6 }}>
          <div style={{ display: "flex", gap: 4, marginBottom: 5 }}>
            <input value={pf.name} onChange={(e) => setPf({ ...pf, name: e.target.value })} placeholder="Person"
              style={{ ...inp, fontSize: 11, padding: "4px 6px", flex: 1 }} />
            <input value={pf.role} onChange={(e) => setPf({ ...pf, role: e.target.value })} placeholder="Role"
              style={{ ...inp, fontSize: 11, padding: "4px 6px", width: 88 }} />
            <button disabled={!pf.name.trim()} onClick={() => { act(() => api("POST", `/api/physicians/${d.id}/contacts/people`, pf)); setPf({ name: "", role: "" }); }}
              style={{ ...btn, fontSize: 10.5, padding: "4px 8px", opacity: pf.name.trim() ? 1 : 0.4 }}>Add person</button>
          </div>
          <div style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
            <select value={f.kind} onChange={(e) => setF({ ...f, kind: e.target.value })} style={{ ...inp, fontSize: 11, padding: "4px 5px" }}>
              {["phone", "email", "fax", "website", "portal"].map((k) => <option key={k} value={k}>{k}</option>)}
            </select>
            <select value={f.purpose} onChange={(e) => setF({ ...f, purpose: e.target.value })} style={{ ...inp, fontSize: 11, padding: "4px 5px" }}>
              {["scheduling", "general", "billing", "records", "reports"].map((k) => <option key={k} value={k}>{k}</option>)}
            </select>
            <select value={f.contact_person_id} onChange={(e) => setF({ ...f, contact_person_id: e.target.value })} style={{ ...inp, fontSize: 11, padding: "4px 5px" }}>
              <option value="">practice</option>
              {contacts.people.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
            </select>
            <input value={f.value} onChange={(e) => setF({ ...f, value: e.target.value })} placeholder="Paste it — multiple numbers split automatically"
              style={{ ...inp, fontSize: 11, padding: "4px 6px", flex: 1, minWidth: 130 }} />
            <button disabled={!f.value.trim()} onClick={() => {
              act(() => api("POST", `/api/physicians/${d.id}/contacts/methods`, { ...f, contact_person_id: f.contact_person_id || null }));
              setF({ ...f, value: "" });
            }} style={{ ...btn, fontSize: 10.5, padding: "4px 8px", opacity: f.value.trim() ? 1 : 0.4 }}>Add</button>
          </div>
        </div>
      )}
    </Section>
  );
}

function CorrespondencePanel({ d, corr, contacts, act, actor }) {
  const [f, setF] = useState({ direction: "outbound", channel: "phone", subject: "", body: "", contact_person_id: "" });
  const CH = { phone: "☎", email: "✉", fax: "⎙", portal: "⌗", meeting: "◎", note: "✎" };
  const submit = () => {
    act(() => api("POST", `/api/physicians/${d.id}/correspondence`, { ...f, contact_person_id: f.contact_person_id || null }));
    setF({ ...f, subject: "", body: "" });
  };
  return (
    <Section title="Correspondence" count={corr.length}>
      <div style={{ background: "#F7F9F8", border: `1px solid ${C.rule}`, padding: 9, marginBottom: 10 }}>
        <div style={{ display: "flex", gap: 4, marginBottom: 5, flexWrap: "wrap" }}>
          {["outbound", "inbound"].map((v) => (
            <button key={v} onClick={() => setF({ ...f, direction: v })}
              style={{ background: f.direction === v ? C.ink : C.surface, color: f.direction === v ? C.surface : C.ink,
                border: `1px solid ${f.direction === v ? C.ink : C.rule}`, padding: "3px 8px", fontSize: 10.5, cursor: "pointer", fontFamily: MONO }}>{v}</button>
          ))}
          <select value={f.channel} onChange={(e) => setF({ ...f, channel: e.target.value })} style={{ ...inp, fontSize: 11, padding: "3px 5px" }}>
            {Object.keys(CH).map((k) => <option key={k} value={k}>{k}</option>)}
          </select>
          <select value={f.contact_person_id} onChange={(e) => setF({ ...f, contact_person_id: e.target.value })} style={{ ...inp, fontSize: 11, padding: "3px 5px" }}>
            <option value="">with…</option>
            {contacts.people.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
          </select>
          <input value={f.subject} onChange={(e) => setF({ ...f, subject: e.target.value })} placeholder="Subject"
            style={{ ...inp, fontSize: 11, padding: "3px 6px", flex: 1, minWidth: 100 }} />
        </div>
        <textarea value={f.body} onChange={(e) => setF({ ...f, body: e.target.value })} rows={2}
          placeholder="What was said. Cities they cover, whether it's their office or rented, rates, declines."
          style={{ ...inp, fontSize: 11.5, padding: "5px 7px", width: "100%", resize: "vertical", fontFamily: SANS }} />
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 5 }}>
          <span style={{ fontFamily: MONO, fontSize: 9, color: actor ? C.muted : C.flag }}>
            {actor ? `logged as ${actor}` : "set your name up top first"}
          </span>
          <div style={{ flex: 1 }} />
          <button disabled={!f.body.trim() && !f.subject.trim()} onClick={submit}
            style={{ ...btn, fontSize: 11, opacity: (f.body.trim() || f.subject.trim()) ? 1 : 0.4 }}>Log it</button>
        </div>
      </div>

      {corr.length === 0 && <Empty>Nothing logged. Every call worth making is worth recording.</Empty>}
      <div style={{ display: "flex", flexDirection: "column" }}>
        {corr.map((c, i) => (
          <div key={c.id} style={{ display: "flex", gap: 9, paddingBottom: 11 }}>
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", flexShrink: 0 }}>
              <span style={{ width: 20, height: 20, borderRadius: "50%", border: `1px solid ${c.direction === "inbound" ? C.travel : C.rule}`,
                background: C.surface, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 10, color: c.direction === "inbound" ? C.travel : C.muted }}>
                {CH[c.channel] || "•"}
              </span>
              {i < corr.length - 1 && <span style={{ width: 1, flex: 1, background: C.ruleSoft, marginTop: 2 }} />}
            </div>
            <div style={{ flex: 1, minWidth: 0, paddingTop: 1 }}>
              <div style={{ display: "flex", gap: 6, alignItems: "baseline", flexWrap: "wrap" }}>
                {c.subject && <span style={{ fontSize: 12, fontWeight: 500 }}>{c.subject}</span>}
                <span style={{ fontFamily: MONO, fontSize: 9, color: C.muted }}>
                  {c.direction} {c.channel}{c.person_name ? ` · ${c.person_name}` : ""}
                </span>
                <div style={{ flex: 1 }} />
                <span style={{ fontFamily: MONO, fontSize: 9, color: C.muted }}>{(c.occurred_at || "").slice(0, 10)}</span>
              </div>
              {c.body && <div style={{ fontSize: 11.5, color: C.ink, marginTop: 3, lineHeight: 1.5, whiteSpace: "pre-wrap" }}>{c.body}</div>}
              <div style={{ display: "flex", gap: 8, marginTop: 3, alignItems: "center" }}>
                <span style={{ fontFamily: MONO, fontSize: 8.5, color: C.muted }}>{c.logged_by}</span>
                {c.outreach_id && (
                  <span style={{ fontFamily: MONO, fontSize: 8, color: C.travel, background: C.travelBg, padding: "1px 4px" }}>
                    call sheet · {c.outreach_status}
                  </span>
                )}
                {(c.attachments || []).map((a) => (
                  <a key={a.id} href={`/api/documents/${a.id}/file`} target="_blank" rel="noreferrer"
                    style={{ fontFamily: MONO, fontSize: 8.5, color: C.travel }}>📎 {a.filename}</a>
                ))}
              </div>
            </div>
          </div>
        ))}
      </div>
    </Section>
  );
}

const DOC_TYPES = [["cv", "CV"], ["licensure", "Licensure"], ["contract", "Contract"], ["fee_schedule", "Fee schedule"],
                   ["scheduling", "Scheduling forms"], ["w9", "W-9"], ["insurance", "Insurance"], ["report_sample", "Report sample"], ["other", "Other"]];
function DocumentsPanel({ d, act }) {
  const [type, setType] = useState("cv");
  const [expires, setExpires] = useState("");
  const [drag, setDrag] = useState(false);
  const [showOld, setShowOld] = useState(false);
  const fileRef = React.useRef(null);
  const docs = d.documents || [];
  const current = docs.filter((x) => x.is_current);
  const old = docs.filter((x) => !x.is_current);

  const send = (file) => act(() => apiUpload(`/api/physicians/${d.id}/documents`, file, { doc_type: type, expires_on: expires || null }));
  const kb = (n) => (n > 1e6 ? (n / 1e6).toFixed(1) + " MB" : Math.max(1, Math.round(n / 1024)) + " KB");
  const expiryTone = (x) => {
    if (!x.expires_on) return null;
    const days = Math.round((new Date(x.expires_on) - Date.now()) / 864e5);
    return days < 0 ? [C.none, "expired"] : days < 60 ? [C.flag, `${days}d left`] : [C.muted, x.expires_on];
  };

  return (
    <Section title="On file" count={current.length}>
      {current.length === 0 && <Empty>Nothing on file. No CV, no licensure, no contract.</Empty>}
      <div style={{ display: "flex", flexDirection: "column", gap: 3, marginBottom: 8 }}>
        {current.map((x) => {
          const ex = expiryTone(x);
          return (
            <div key={x.id} style={{ display: "flex", gap: 7, alignItems: "baseline", border: `1px solid ${C.rule}`, padding: "5px 8px" }}>
              <span style={{ fontFamily: MONO, fontSize: 8, color: C.muted, width: 62, flexShrink: 0, textTransform: "uppercase" }}>
                {(DOC_TYPES.find((t) => t[0] === x.doc_type) || ["", x.doc_type])[1]}
              </span>
              <a href={`/api/documents/${x.id}/file`} target="_blank" rel="noreferrer"
                style={{ fontSize: 11.5, color: C.ink, flex: 1, textDecoration: "none", borderBottom: `1px dotted ${C.rule}`, minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                {x.title || x.filename}
              </a>
              {x.version > 1 && <span style={{ fontFamily: MONO, fontSize: 8, color: C.muted }}>v{x.version}</span>}
              {ex && <span style={{ fontFamily: MONO, fontSize: 8.5, color: ex[0] }}>{ex[1]}</span>}
              <span style={{ fontFamily: MONO, fontSize: 8, color: C.muted }}>{kb(x.byte_size || 0)}</span>
              <button onClick={() => act(() => api("DELETE", `/api/documents/${x.id}`))}
                style={{ background: "none", border: "none", color: C.muted, cursor: "pointer", fontSize: 13, lineHeight: 1, padding: 0 }} aria-label="Delete">×</button>
            </div>
          );
        })}
      </div>
      {old.length > 0 && (
        <div style={{ marginBottom: 8 }}>
          <button onClick={() => setShowOld(!showOld)} style={linkBtn}>{showOld ? "hide" : "show"} {old.length} superseded</button>
          {showOld && old.map((x) => (
            <div key={x.id} style={{ display: "flex", gap: 7, fontSize: 10.5, color: C.muted, padding: "2px 0", opacity: 0.75 }}>
              <span style={{ fontFamily: MONO, fontSize: 8 }}>v{x.version}</span>
              <a href={`/api/documents/${x.id}/file`} target="_blank" rel="noreferrer" style={{ color: C.muted, flex: 1 }}>{x.title || x.filename}</a>
              <span style={{ fontFamily: MONO, fontSize: 8 }}>{(x.uploaded_at || "").slice(0, 10)}</span>
            </div>
          ))}
        </div>
      )}

      <div onDragOver={(e) => { e.preventDefault(); setDrag(true); }} onDragLeave={() => setDrag(false)}
        onDrop={(e) => { e.preventDefault(); setDrag(false); if (e.dataTransfer.files[0]) send(e.dataTransfer.files[0]); }}
        onClick={() => fileRef.current && fileRef.current.click()}
        style={{ border: `1px dashed ${drag ? C.travel : C.rule}`, background: drag ? C.travelBg : "transparent",
          padding: "10px 8px", textAlign: "center", cursor: "pointer" }}>
        <input ref={fileRef} type="file" style={{ display: "none" }} onChange={(e) => e.target.files[0] && send(e.target.files[0])} />
        <div style={{ fontSize: 11, color: C.muted }}>Drop a file, or click to choose</div>
        <div style={{ display: "flex", gap: 4, justifyContent: "center", marginTop: 6 }} onClick={(e) => e.stopPropagation()}>
          <select value={type} onChange={(e) => setType(e.target.value)} style={{ ...inp, fontSize: 10.5, padding: "3px 5px" }}>
            {DOC_TYPES.map(([v, l]) => <option key={v} value={v}>{l}</option>)}
          </select>
          <input type="date" value={expires} onChange={(e) => setExpires(e.target.value)} title="Expiry (licensure, insurance)"
            style={{ ...inp, fontSize: 10.5, padding: "3px 5px" }} />
        </div>
      </div>
      <div style={{ fontSize: 9.5, color: C.muted, marginTop: 4 }}>Same file twice dedupes. A newer one supersedes and keeps the old version.</div>
    </Section>
  );
}

function FeesPanel({ d, act }) {
  const [f, setF] = useState({ service_code: "IME", amount: "", unit: "flat" });
  const fees = d.fees || [];
  const money = (c) => "$" + (c / 100).toLocaleString(undefined, { maximumFractionDigits: 0 });
  return (
    <Section title="What they charge" count={fees.length}>
      {fees.length === 0 && <Empty>No rates on file. Sales stalls on pricing every time.</Empty>}
      <div style={{ display: "flex", flexDirection: "column", gap: 2, marginBottom: 7 }}>
        {fees.map((x) => (
          <div key={x.id} style={{ display: "flex", gap: 7, alignItems: "baseline", fontSize: 11.5 }}>
            <span style={{ fontFamily: MONO, fontSize: 9, color: C.muted, width: 70, flexShrink: 0 }}>{x.service_code}</span>
            <span style={{ fontFamily: COND, fontSize: 14, fontWeight: 600, flex: 1 }}>{money(x.amount_cents)}
              <span style={{ fontFamily: MONO, fontSize: 9, color: C.muted, fontWeight: 400 }}>{x.unit !== "flat" ? ` / ${x.unit}` : ""}</span>
            </span>
            {x.document_id && <a href={`/api/documents/${x.document_id}/file`} target="_blank" rel="noreferrer" style={{ fontFamily: MONO, fontSize: 8.5, color: C.travel }}>source</a>}
          </div>
        ))}
      </div>
      <div style={{ display: "flex", gap: 4 }}>
        <select value={f.service_code} onChange={(e) => setF({ ...f, service_code: e.target.value })} style={{ ...inp, fontSize: 11, padding: "4px 5px" }}>
          {["IME", "AME", "RECORD_REVIEW", "RUSH", "NO_SHOW", "DEPOSITION"].map((k) => <option key={k}>{k}</option>)}
        </select>
        <input value={f.amount} onChange={(e) => setF({ ...f, amount: e.target.value })} placeholder="$" inputMode="decimal"
          style={{ ...inp, fontSize: 11, padding: "4px 6px", width: 64 }} />
        <select value={f.unit} onChange={(e) => setF({ ...f, unit: e.target.value })} style={{ ...inp, fontSize: 11, padding: "4px 5px" }}>
          {["flat", "hour", "page", "case"].map((k) => <option key={k}>{k}</option>)}
        </select>
        <button disabled={!parseFloat(f.amount)} onClick={() => {
          act(() => api("POST", `/api/physicians/${d.id}/fees`, { service_code: f.service_code, amount_cents: Math.round(parseFloat(f.amount) * 100), unit: f.unit }));
          setF({ ...f, amount: "" });
        }} style={{ ...btn, fontSize: 10.5, padding: "4px 8px", opacity: parseFloat(f.amount) ? 1 : 0.4 }}>Add</button>
      </div>
    </Section>
  );
}

function CallSheet({ outreach, resolveItem, reopenItem, assignItem, actor }) {
  const [note, setNote] = useState({});
  const open = outreach.filter((o) => o.status === "open" || o.status === "in_progress");
  const closed = outreach.filter((o) => o.status === "resolved" || o.status === "declined");
  const PRIORITY = { 1: ["High", C.none], 2: ["Med", C.flag], 3: ["Low", C.muted] };

  return (
    <div>
      <p style={{ fontSize: 12.5, color: C.muted, margin: "0 0 6px", maxWidth: 680, lineHeight: 1.65 }}>
        Every provider whose coverage can't be established from the source file. Each call either puts someone on a
        pin or proves you need to hire onto it. This queue lives on the server — assignments and outcomes are shared,
        and resolving an item stamps who and when.
      </p>
      <p style={{ fontSize: 11, color: C.muted, margin: "0 0 16px" }}>
        {open.length} open · {closed.length} closed{!actor && <span style={{ color: C.flag }}> · set your name up top so the audit log means something</span>}
      </p>

      {open.length === 0 ? (
        <div style={{ background: C.surface, border: `1px solid ${C.rule}`, padding: 32, textAlign: "center" }}>
          <div style={{ fontFamily: COND, fontSize: 17, fontWeight: 600, marginBottom: 5 }}>Call sheet clear</div>
          <div style={{ fontSize: 12.5, color: C.muted }}>Every provider's coverage is on the record. The ledger is now trustworthy.</div>
        </div>
      ) : (
        <div style={{ background: C.surface, border: `1px solid ${C.rule}` }}>
          {open.map((o) => {
            const [plabel, ptone] = PRIORITY[o.priority] || PRIORITY[3];
            return (
              <div key={o.id} style={{ padding: "13px 15px", borderBottom: `1px solid ${C.ruleSoft}` }}>
                <div style={{ display: "flex", gap: 12, alignItems: "flex-start" }}>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: 13, fontWeight: 500 }}>
                      {o.full_name || "(unassigned target)"}
                      {o.is_qme ? <span style={{ fontFamily: MONO, fontSize: 8.5, color: C.travel, background: C.travelBg, padding: "1px 4px", marginLeft: 6 }}>QME</span> : null}
                      {o.specialty ? <span style={{ fontFamily: MONO, fontSize: 10.5, color: C.muted, marginLeft: 8 }}>{o.specialty}</span> : null}
                      <span style={{ fontFamily: MONO, fontSize: 8.5, color: ptone, border: `1px solid ${ptone}`, padding: "0 4px", marginLeft: 8 }}>{plabel}</span>
                    </div>
                    <div style={{ fontSize: 11.5, color: C.flag, marginTop: 4, lineHeight: 1.5 }}>{o.prompt}</div>
                    <div style={{ fontFamily: MONO, fontSize: 10.5, color: C.muted, marginTop: 5, display: "flex", gap: 14, flexWrap: "wrap" }}>
                      {o.phone && <span>{o.phone}</span>}{o.email && <span>{o.email}</span>}
                    </div>
                  </div>
                  <div style={{ display: "flex", flexDirection: "column", gap: 5, alignItems: "flex-end" }}>
                    <select value={o.assigned_to || ""} onChange={(e) => assignItem(o.id, e.target.value)}
                      style={{ ...inp, fontSize: 11, padding: "3px 6px", width: 124 }} aria-label={`Assign ${o.full_name}`}>
                      <option value="">unassigned</option>
                      {[...new Set([actor, "Melanie", "Andy"].filter(Boolean))].map((w) => <option key={w} value={w}>{w}</option>)}
                    </select>
                    <span style={{ fontFamily: MONO, fontSize: 9, color: o.status === "in_progress" ? C.travel : C.muted }}>{o.status}</span>
                  </div>
                </div>
                <div style={{ display: "flex", gap: 6, marginTop: 9 }}>
                  <input value={note[o.id] || ""} onChange={(e) => setNote({ ...note, [o.id]: e.target.value })}
                    placeholder="What did they say? (cities, office or rented space, declines)"
                    style={{ ...inp, flex: 1, fontSize: 11.5, padding: "5px 8px" }} />
                  <button onClick={() => { resolveItem(o.id, note[o.id]); setNote({ ...note, [o.id]: "" }); }} style={{ ...btn, fontSize: 11 }}>Resolve</button>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {closed.length > 0 && (
        <div style={{ marginTop: 16 }}>
          <div style={{ fontFamily: MONO, fontSize: 9.5, letterSpacing: "0.09em", textTransform: "uppercase", color: C.muted, marginBottom: 7 }}>Closed ({closed.length})</div>
          <div style={{ background: C.surface, border: `1px solid ${C.rule}` }}>
            {closed.map((o) => (
              <div key={o.id} style={{ display: "flex", gap: 12, padding: "9px 15px", borderBottom: `1px solid ${C.ruleSoft}`, alignItems: "baseline" }}>
                <span style={{ fontSize: 12.5, flex: 1 }}>{o.full_name}</span>
                {o.outcome_note && <span style={{ fontSize: 11, color: C.muted, flex: 2 }}>{o.outcome_note}</span>}
                <span style={{ fontFamily: MONO, fontSize: 9.5, color: C.muted }}>{(o.resolved_at || "").slice(0, 10)}</span>
                <button onClick={() => reopenItem(o.id)} style={{ background: "none", border: "none", color: C.travel, fontSize: 10.5, cursor: "pointer" }}>reopen</button>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

const hcell = { padding: "7px 12px", fontFamily: MONO, fontSize: 9, letterSpacing: "0.08em", textTransform: "uppercase", color: C.muted };
const inp = { padding: "7px 9px", border: `1px solid ${C.rule}`, background: C.surface, fontSize: 12.5, color: C.ink, fontFamily: SANS, borderRadius: 0 };
const btn = { padding: "6px 11px", border: `1px solid ${C.ink}`, background: C.ink, color: C.surface, fontSize: 11.5, cursor: "pointer", fontFamily: SANS, borderRadius: 0 };
